/** All translations for zizhitongjian ch.004 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起閼逢困敦，盡著雍困敦，凡二十五年。", literal: "From Efayin Gundun through Zhuayong Gundun; twenty-five years in all.", idiomatic: "From Efayin Gundun through Zhuayong Gundun—twenty-five years in all." },
  { zh: "1楚懷王亡歸。", literal: "1. King Huai of Chu fled to return home.", idiomatic: "1. King Huai of Chu fled homeward." },
  { zh: "秦人覺之，遮楚道。", literal: "The men of Qin discovered it and blocked the Chu road.", idiomatic: "Qin discovered it and blocked the roads to Chu." },
  { zh: "懷王從間道走趙。", literal: "King Huai went by a secret path toward Zhao.", idiomatic: "King Huai took a bypath and fled toward Zhao." },
  { zh: "趙主父在代，趙人不敢受。", literal: "The Lord-Father of Zhao was at Dai; the Zhao people did not dare receive him.", idiomatic: "The Lord-Father of Zhao was in Dai; the Zhao people dared not shelter him." },
  { zh: "懷王將走魏，秦人追及之，以歸。", literal: "King Huai was about to go to Wei; the men of Qin overtook him and brought him back.", idiomatic: "King Huai was about to flee to Wei when Qin pursuers caught him and brought him back." },
  { zh: "1楚懷王發病，薨於秦，秦人歸其喪。", literal: "1. King Huai of Chu fell ill, died in Qin; the men of Qin returned his coffin.", idiomatic: "1. King Huai of Chu fell ill and died in Qin; Qin sent his coffin home." },
  { zh: "楚人皆憐之，如悲親戚。", literal: "The Chu people all pitied him, as if mourning kin.", idiomatic: "The Chu people pitied him as they would mourn their own kin." },
  { zh: "諸侯由是不直秦。", literal: "From this the feudal lords did not regard Qin as upright.", idiomatic: "From this the feudal lords ceased to regard Qin as righteous." },
  { zh: "2齊、韓、魏、趙、宋同擊秦，至鹽氏而還。", literal: "2. Qi, Han, Wei, Zhao, and Song together attacked Qin, reached Yanshi, and returned.", idiomatic: "2. Qi, Han, Wei, Zhao, and Song jointly attacked Qin, reached Yanshi, and withdrew." },
  { zh: "秦與韓武遂、與魏封陵以和。", literal: "Qin made peace with Han at Wusui and with Wei at Fengling.", idiomatic: "Qin made peace with Han at Wusui and with Wei at Fengling." },
  { zh: "3趙主父行新地，遂出代；", literal: "3. The Lord-Father of Zhao toured the new lands, then left Dai;", idiomatic: "3. The Lord-Father of Zhao toured the new territories, then left Dai;" },
  { zh: "西遇樓煩王於西河而致其兵。", literal: "going west he met the king of Loufan at Xihe and took over his troops.", idiomatic: "going west he met the king of Loufan on the Xi River and absorbed his army." },
  { zh: "4魏襄王薨，子昭王〔遫〕立<ref>子昭王〔遫〕立據《史記·魏世家》索隱引《世本》補。", literal: "4. King Xiang of Wei died; his son King Zhao [Su] succeeded<ref>King Zhao [Su] succeeded—\"Su\" supplemented per Suoyin to the \"House of Wei\" in the Records of the Grand Historian citing the Shiben.", idiomatic: "4. King Xiang of Wei died; his son King Zhao [Su] succeeded<ref>\"Su\" for King Zhao's succession is added from Suoyin to \"House of Wei\" citing the Shiben." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "5韓襄王薨，子釐王咎立。", literal: "5. King Xiang of Han died; his son King Xi Jiu succeeded.", idiomatic: "5. King Xiang of Han died; his son King Xi Jiu succeeded." },
  { zh: "1秦尉錯伐魏襄城。", literal: "1. Wei Cuo, Qin Vice-Marshal, attacked Xiangcheng of Wei.", idiomatic: "1. Qin Vice-Marshal Wei Cuo attacked Xiangcheng in Wei." },
  { zh: "2趙主父與齊、燕共滅中山，遷其王於膚施。", literal: "2. The Lord-Father of Zhao with Qi and Yan jointly destroyed Zhongshan and moved its king to Fushi.", idiomatic: "2. The Lord-Father of Zhao, with Qi and Yan, destroyed Zhongshan and relocated its king to Fushi." },
  { zh: "歸，行賞，大赦，置酒，酺五日。", literal: "On his return he distributed rewards, proclaimed a general amnesty, set out wine, and held communal feasting for five days.", idiomatic: "On his return he rewarded his men, proclaimed a general amnesty, set out wine, and held five days of public revelry." },
  { zh: "3趙主父封其長子章於代，號曰安陽君。", literal: "3. The Lord-Father of Zhao enfeoffed his eldest son Zhang at Dai, styling him Lord Anyang.", idiomatic: "3. The Lord-Father enfeoffed his eldest son Zhang in Dai as Lord Anyang." },
  { zh: "安陽君素侈，心不服其弟。", literal: "Lord Anyang had always been extravagant; in his heart he did not submit to his younger brother.", idiomatic: "Lord Anyang had long been extravagant and inwardly refused to bow to his younger brother." },
  { zh: "主父使田不禮相之。", literal: "The Lord-Father sent Tian Buli to assist him.", idiomatic: "The Lord-Father appointed Tian Buli as his chief minister." },
  { zh: "李兌謂肥義曰：「公子章強壯而志驕，黨眾而欲大，田不禮忍殺而驕，二人相得，必有陰謀。", literal: "Li Dui said to Fei Yi: \"Lord Zhang is strong and his will is proud; his faction is numerous and his desires are great; Tian Buli is cruel in killing and proud—the two suit each other; there must be a secret plot.", idiomatic: "Li Dui said to Fei Yi: \"Lord Zhang is strong-bodied and proud in ambition; his faction is large and his desires vast; Tian Buli is ruthless and murderous, proud in temper—the two suit each other. There must be a secret plot afoot." },
  { zh: "夫小人有欲，輕慮淺謀，徒見其利，不顧其害，難必不久矣。", literal: "When petty men have desires, they lightly consider and shallowly plan, seeing only the profit and not the harm—calamity cannot be long in coming.", idiomatic: "Petty men with desires think lightly and plan shallowly; they see only gain, never harm—disaster cannot be far off." },
  { zh: "子任重而勢大，亂之所始而禍之所集也。", literal: "Your burden is heavy and your power is great—you are where disorder begins and where calamity gathers.", idiomatic: "Your burden is heavy and your power great—you stand where disorder begins and calamity gathers." },
  { zh: "子奚不稱疾毋出而傳政於公子成，毋為禍梯，不亦可乎！", literal: "Why do you not plead illness, stay within, and transfer government to Lord Cheng—do not be a ladder for calamity; would that not do?", idiomatic: "Why not plead illness, stay indoors, and hand power to Lord Cheng? Do not be the ladder by which disaster climbs—is that not better?" },
  { zh: "」肥義曰：「昔者主父以王屬義也，曰：『毋變而度，毋易而慮，堅守一心，以歿而世。", literal: "\" Fei Yi said: \"Formerly the Lord-Father entrusted the king to Yi, saying: 'Do not change your measure; do not alter your deliberations; firmly keep one heart, until death and for generations.", idiomatic: "\" Fei Yi said: \"Once the Lord-Father entrusted the king to me, saying: 'Do not change your standard; do not shift your plans; hold one heart steadfast, unto death and for generations to come." },
  { zh: "』義再拜受命而籍之。", literal: "' Yi twice bowed, received the charge, and recorded it.", idiomatic: "' I bowed twice, accepted the charge, and set it down in writing." },
  { zh: "今畏不禮之難而忘吾籍，變孰大焉！", literal: "Now, fearing Buli's peril and forgetting my record—what change could be greater!", idiomatic: "Now, fearing Buli's threat and forgetting what I recorded—what betrayal could be greater?" },
  { zh: "諺曰：『死者復生，生者不愧。", literal: "A proverb says: 'If the dead could live again, the living would have no shame.", idiomatic: "A proverb says: 'If the dead could rise again, the living would feel no shame." },
  { zh: "』吾欲全吾言，安得全吾身乎！", literal: "' I wish to keep my words whole—how can I keep my person whole!", idiomatic: "' I wish to keep my word whole—how can I keep my body whole?" },
  { zh: "子則有賜而忠我矣。", literal: "You have shown kindness and been loyal to me.", idiomatic: "You have done me a kindness and been loyal to me." },
  { zh: "雖然，吾言已在前矣，終不敢失！", literal: "Even so, my words are already set forth—I ultimately dare not fail them!", idiomatic: "Even so, my pledge stands already—I dare not break it in the end!" },
  { zh: "」李兌曰：「諾。", literal: "\" Li Dui said: \"Agreed.", idiomatic: "\" Li Dui said: \"Very well." },
  { zh: "子勉之矣！", literal: "Press on, sir!", idiomatic: "Do your utmost, sir!" },
  { zh: "吾見子已今年耳。", literal: "I shall see you only within this year.", idiomatic: "I expect to see you only within this year." },
  { zh: "」涕泣而出。", literal: "\" He wept as he went out.", idiomatic: "\" He left in tears." },
  { zh: "李兌數見公子成以備田不禮。", literal: "Li Dui repeatedly visited Lord Cheng to guard against Tian Buli.", idiomatic: "Li Dui repeatedly visited Lord Cheng to prepare against Tian Buli." },
  { zh: "肥義謂信期曰：「公子章與田不禮聲善而實惡，內得主而外為暴，矯令以擅一旦之命，不難為也。", literal: "Fei Yi said to Xin Qi: \"Lord Zhang and Tian Buli sound friendly but are in truth hostile; inwardly they have a master, outwardly they act violently—forging orders to seize command for a day is not hard for them.", idiomatic: "Fei Yi said to Xin Qi: \"Lord Zhang and Tian Buli sound cordial but are in truth at odds; they have backing within and act violently without—forging orders to seize power for a day would not be hard for them." },
  { zh: "今吾憂之，夜而忘寐，饑而忘食，盜出入不可以不備<ref>盜出入不可以不備章校「十二行本無『以』字；", literal: "Now I worry over this—at night I forget sleep, when hungry I forget food; thieves coming and going cannot go unguarded<ref>Thieves coming and going cannot go unguarded—Zhang's collation: the twelve-line edition lacks the character \"yi\";", idiomatic: "I worry so that at night I forget sleep and when hungry I forget food; thieves entering and leaving must be guarded against<ref>\"must be guarded against\"—Zhang's collation: the twelve-line edition lacks \"yi\";" },
  { zh: "乙十一行本同。", literal: "the Y eleven-line edition agrees.", idiomatic: "the Y eleven-line edition agrees;" },
  { zh: "」《史記·趙世家》同，但不刪亦可。", literal: "\" The \"House of Zhao\" in the Records of the Grand Historian agrees; yet not deleting it is also acceptable.", idiomatic: "\" The \"House of Zhao\" in Records of the Grand Historian agrees; leaving the character in is also acceptable." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "自今以來，有召王者必見吾面，我將以身先之。", literal: "From now on, whenever the king is summoned, he must see my face first; I will put my body before him.", idiomatic: "From now on, whoever summons the king must pass me first; I will put my body in the way." },
  { zh: "無故而後王可入也。", literal: "Only if there is no cause may the king enter afterward.", idiomatic: "Only if there is no cause for alarm may the king enter after." },
  { zh: "」信期曰：「善。", literal: "\" Xin Qi said: \"Good.", idiomatic: "\" Xin Qi said: \"Well said." },
  { zh: "主父使惠文王朝群臣而自從旁窺之，見其長子累然也，反北面為臣。", literal: "The Lord-Father had King Huiwen attend court before the ministers while he himself watched from the side; he saw his eldest son worn and abject, turning north to serve as a subject.", idiomatic: "The Lord-Father had King Huiwen hold court before the ministers while he watched from the side; he saw his eldest son worn down, bowing north as a subject." },
  { zh: "詘於其弟，心憐之，於是乃欲分趙而王公子章於代，計未決而輟。", literal: "Subdued before his younger brother, his heart pitied him; thereupon he wished to divide Zhao and make Lord Zhang king in Dai—the plan was not settled and was dropped.", idiomatic: "Humbled before his younger brother, he pitied him in his heart and wished to split Zhao and make Lord Zhang king in Dai—but the plan was never settled and was abandoned." },
  { zh: "主父及王游沙丘，異宮，公子章、田不禮以其徒作亂，詐以主父令召王。", literal: "The Lord-Father and the king were touring Sand Hill in separate palaces; Lord Zhang and Tian Buli with their followers raised a revolt, falsely using the Lord-Father's order to summon the king.", idiomatic: "The Lord-Father and the king were at Sand Hill in separate palaces; Lord Zhang and Tian Buli raised a revolt with their followers, forging the Lord-Father's order to summon the king." },
  { zh: "肥義先入，殺之。", literal: "Fei Yi entered first and killed him.", idiomatic: "Fei Yi went in first and killed him." },
  { zh: "高信即與王戰。", literal: "Gao Xin immediately fought with the king.", idiomatic: "Gao Xin immediately fought at the king's side." },
  { zh: "公子成與李兌自國至，乃起四邑之兵入距難，殺公子章及田不禮，滅其黨。", literal: "Lord Cheng and Li Dui came from the capital, then raised troops from four districts to enter and repel the trouble, killing Lord Zhang and Tian Buli and exterminating their faction.", idiomatic: "Lord Cheng and Li Dui came from the capital, raised troops from four districts, marched in to suppress the revolt, killed Lord Zhang and Tian Buli, and wiped out their faction." },
  { zh: "公子成為相，號安平君；", literal: "Lord Cheng became chancellor, styled Lord of Anping;", idiomatic: "Lord Cheng became chancellor, styled Lord of Anping;" },
  { zh: "李兌為司寇。", literal: "Li Dui became Minister of Justice.", idiomatic: "Li Dui became Minister of Justice." },
  { zh: "是時惠文王少，成、兌專政。", literal: "At this time King Huiwen was young; Cheng and Dui held sole power.", idiomatic: "King Huiwen was still young; Cheng and Dui held sole power." },
  { zh: "公子章之敗也，往走主父，主父開之。", literal: "When Lord Zhang was defeated, he fled to the Lord-Father; the Lord-Father opened to him.", idiomatic: "When Lord Zhang was defeated, he fled to the Lord-Father, who admitted him." },
  { zh: "成、兌因圍主父〔宮〕<ref>成兌因圍主父〔宮〕章校「十二行本『父』下有『宮』字；", literal: "Cheng and Dui thereupon besieged the Lord-Father's [palace]<ref>Cheng and Dui besieged the Lord-Father's [palace]—Zhang's collation: in the twelve-line edition after \"Father\" there is the character \"palace\";", idiomatic: "Cheng and Dui then besieged the Lord-Father's [palace]<ref>\"palace\" after \"Father\"—Zhang's collation: the twelve-line edition has \"palace\";" },
  { zh: "乙十一行本同；", literal: "the Y eleven-line edition agrees;", idiomatic: "the Y eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同；", literal: "Zhang's collation agrees;", idiomatic: "Zhang's collation agrees;" },
  { zh: "退齋校同。", literal: "Tuizhai's collation agrees.", idiomatic: "Tuizhai's collation agrees." },
  { zh: "」《史記·趙世家》同，據補。", literal: "\" The \"House of Zhao\" in the Records of the Grand Historian agrees; supplemented accordingly.", idiomatic: "\" The \"House of Zhao\" in Records of the Grand Historian agrees; \"palace\" added accordingly." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "公子章死，成、兌謀曰：「以章故，圍主父；", literal: "Lord Zhang died; Cheng and Dui plotted, saying: \"Because of Zhang we besieged the Lord-Father;", idiomatic: "After Lord Zhang died, Cheng and Dui plotted: \"We besieged the Lord-Father on Zhang's account;" },
  { zh: "即解兵，吾屬夷矣！", literal: "if we now disband the troops, our clans will be exterminated!", idiomatic: "if we disband now, our clans will be wiped out!" },
  { zh: "」乃遂圍之，令：「宮中人後出者夷！", literal: "\" They then continued the siege and ordered: \"Whoever leaves the palace last shall be exterminated!", idiomatic: "\" They kept the siege and ordered: \"Whoever leaves the palace last shall be killed!" },
  { zh: "」宮中人悉出。", literal: "\" Everyone in the palace came out.", idiomatic: "\" Everyone in the palace came out." },
  { zh: "主父欲出不得，又不得食，探雀鷇而食之。", literal: "The Lord-Father wished to go out but could not; he also could not obtain food, and pulled fledglings from nests to eat.", idiomatic: "The Lord-Father could neither get out nor get food; he pulled nestlings from the eaves and ate them." },
  { zh: "三月餘，餓死沙丘宮。", literal: "After more than three months he starved to death in Sand Hill Palace.", idiomatic: "After more than three months he starved to death in Sand Hill Palace." },
  { zh: "主父定死，乃發喪赴諸侯。", literal: "Once the Lord-Father's death was fixed, they sent out mourning to the feudal lords.", idiomatic: "Once his death was certain, they announced mourning to the feudal lords." },
  { zh: "主父初以長子章為太子，後得吳娃，愛之，為不出者數歲。", literal: "At first the Lord-Father had made his eldest son Zhang crown prince; later he obtained the Wu girl, loved her, and for several years did not go out.", idiomatic: "At first the Lord-Father had made his eldest son Zhang crown prince; later he won the Wu girl, loved her, and for years scarcely left his chambers." },
  { zh: "生子何，乃廢太子章而立之。", literal: "She bore a son, He; he then deposed Crown Prince Zhang and established him.", idiomatic: "She bore a son, He; he deposed Zhang and made He crown prince." },
  { zh: "吳娃死，愛馳；", literal: "When the Wu girl died, his love ran wild;", idiomatic: "When the Wu girl died, his passion waned;" },
  { zh: "憐故太子，欲兩王之，猶豫未決，故亂起。", literal: "pitying the former crown prince, he wished to make both kings; he hesitated and could not decide—therefore disorder arose.", idiomatic: "pitying the former crown prince, he wished to split the realm between the two; he hesitated and could not decide—so the revolt broke out." },
  { zh: "4秦樓緩免相，魏冉代之。", literal: "4. Lou Yuan of Qin was removed as chancellor; Wei Ran replaced him.", idiomatic: "4. Qin dismissed Lou Yuan as chancellor; Wei Ran replaced him." },
  { zh: "1秦敗魏師于解。", literal: "1. Qin defeated the Wei army at Xie.", idiomatic: "1. Qin defeated the Wei army at Xie." },
  { zh: "1韓公孫喜、魏人伐秦。", literal: "1. Gongsun Xi of Han and men of Wei attacked Qin.", idiomatic: "1. Gongsun Xi of Han and Wei forces attacked Qin." },
  { zh: "穰侯薦左更白起於秦王以代向壽將兵，敗魏師、韓師於伊闕，斬首二十四萬級，虜公孫喜，拔五城。", literal: "The Marquis of Rang recommended Left Senior Bai Qi to the king of Qin to replace Xiang Shou in command of the army; he defeated the Wei and Han armies at Yique, beheaded two hundred forty thousand, captured Gongsun Xi, and took five cities.", idiomatic: "The Marquis of Rang recommended Left Senior Bai Qi to the king of Qin to replace Xiang Shou as commander; Bai Qi routed the Wei and Han armies at Yique, took two hundred forty thousand heads, captured Gongsun Xi, and seized five cities." },
  { zh: "秦王以白起為國尉。", literal: "The king of Qin made Bai Qi National Marshal.", idiomatic: "The king of Qin appointed Bai Qi National Marshal." },
  { zh: "2秦王遺楚王書曰：「楚倍秦，秦且率諸侯伐楚，願王之飭士卒，得一樂戰！", literal: "2. The king of Qin sent a letter to the king of Chu, saying: \"Chu has turned against Qin; Qin is about to lead the feudal lords to attack Chu. I wish Your Majesty to drill your soldiers so we may have a joyous battle!", idiomatic: "2. The king of Qin wrote the king of Chu: \"Chu has betrayed Qin; Qin will soon lead the feudal lords against Chu. Drill your troops, Majesty—we may yet enjoy a good fight!" },
  { zh: "」楚王患之，乃復與秦和親。", literal: "\" The king of Chu was troubled by this and thereupon renewed kinship peace with Qin.", idiomatic: "\" The king of Chu was alarmed and renewed a marriage alliance with Qin." },
  { zh: "1楚襄王迎婦於秦。", literal: "1. King Xiang of Chu welcomed a bride from Qin.", idiomatic: "1. King Xiang of Chu took a bride from Qin." },
  { zh: "::臣光曰：甚哉秦之無道也，殺其父而劫其子；", literal: ":: Master Guang said: How utterly lawless is Qin—killing a father and coercing the son;", idiomatic: ":: Master Guang said: How lawless Qin is—killing the father and holding the son hostage;" },
  { zh: "楚之不競也，忍其父而婚其仇！", literal: "how unable to contend is Chu—enduring its father's death and marrying its enemy!", idiomatic: "how unable to contend is Chu—bearing its father's death and wedding its enemy!" },
  { zh: "嗚呼！", literal: "Alas!", idiomatic: "Alas!" },
  { zh: "楚之君誠得其道，臣誠得其人，秦雖強，烏得陵之哉！", literal: "Had the ruler of Chu truly possessed the Way and his ministers truly possessed the men, though Qin were strong—how could it have bullied Chu!", idiomatic: "Had the ruler of Chu truly held the Way and his ministers truly held worthy men, however strong Qin was—how could it have lorded over Chu!" },
  { zh: "善乎荀卿論之曰：「夫道，善用之則百里之地可以獨立，不善用之則楚六千里而為仇人役。", literal: "Well said is Xun Qing's discussion: \"The Way—well used, a hundred-li domain can stand alone; ill used, Chu's six thousand li serve an enemy.", idiomatic: "Xun Qing put it well: \"The Way—well used, a domain of a hundred li can stand alone; ill used, Chu's six thousand li become slaves to an enemy." },
  { zh: "」故人主不務得道而廣有其勢，是其所以危也。", literal: "\" Therefore when a lord does not strive for the Way but broadly possesses mere power—that is why he is in peril.", idiomatic: "\" When a ruler does not pursue the Way but only amasses power—that is why he falls into peril." },
  { zh: "2秦魏冉謝病免，以客卿燭壽為丞相。", literal: "2. Wei Ran of Qin pleaded illness and was dismissed; the guest-minister Zhu Shou was made chancellor.", idiomatic: "2. Wei Ran of Qin resigned on grounds of illness; the guest-minister Zhu Shou became chancellor." },
  { zh: "1秦伐韓，拔宛。", literal: "1. Qin attacked Han and took Wan.", idiomatic: "1. Qin attacked Han and seized Wan." },
  { zh: "2秦燭壽免。", literal: "2. Zhu Shou of Qin was dismissed.", idiomatic: "2. Qin dismissed Zhu Shou." },
  { zh: "魏冉復為丞相，封於穰與陶，謂之穰侯。", literal: "Wei Ran again became chancellor, was enfeoffed at Rang and Tao, and was styled the Marquis of Rang.", idiomatic: "Wei Ran again became chancellor, was enfeoffed at Rang and Tao, and was called the Marquis of Rang." },
  { zh: "又封公子市於宛，公子悝於鄧。", literal: "He also enfeoffed Lord Shi at Wan and Lord Kui at Deng.", idiomatic: "He also enfeoffed Lord Shi at Wan and Lord Kui at Deng." },
  { zh: "1魏入河東地四百里、韓入武遂地二百里于秦。", literal: "1. Wei ceded four hundred li of Hedong territory and Han ceded two hundred li of Wusui territory to Qin.", idiomatic: "1. Wei ceded four hundred li in Hedong and Han ceded two hundred li at Wusui to Qin." },
  { zh: "2魏芒卯始以詐見重。", literal: "2. Mang Mao of Wei first came to be valued for his cunning.", idiomatic: "2. Mang Mao of Wei first won favor through deceit." },
  { zh: "1秦大良造白起、客卿錯伐魏，至軹，取城大小六十一。", literal: "1. Bai Qi, Qin Grand Minister of Construction, and the guest-minister Cuo attacked Wei, reached Zhi, and took sixty-one cities large and small.", idiomatic: "1. Qin Grand Minister Bai Qi and guest-minister Cuo attacked Wei, reached Zhi, and took sixty-one cities large and small." },
  { zh: "1冬，十月，秦王稱西帝，遣使立齊王為東帝，欲約與共伐趙。", literal: "1. In winter, the tenth month, the king of Qin styled himself Western Emperor and sent envoys to establish the king of Qi as Eastern Emperor, wishing to covenant with him to attack Zhao jointly.", idiomatic: "1. In winter, the tenth month, the king of Qin took the title Western Emperor and sent envoys to make the king of Qi Eastern Emperor, proposing a joint attack on Zhao." },
  { zh: "蘇代自燕來，齊王曰：「秦使魏冉致帝，子以為何如？", literal: "Su Dai came from Yan; the king of Qi said: \"Qin sent Wei Ran to offer the title of emperor—what do you think?", idiomatic: "Su Dai came from Yan; the king of Qi said: \"Qin sent Wei Ran to offer the imperial title—what do you think?" },
  { zh: "」對曰：「願王受之而勿稱也。", literal: "\" He answered: \"I wish Your Majesty to accept it but not proclaim it.", idiomatic: "\" He answered: \"Accept it, Majesty, but do not proclaim it yourself." },
  { zh: "秦稱之，天下安之，王乃稱之，無後也。", literal: "If Qin proclaims it and the realm is at peace, then Your Majesty may proclaim it—you will not be late.", idiomatic: "Let Qin proclaim it first; if the realm accepts that, then proclaim it yourself—you will not be behindhand." },
  { zh: "秦稱之，天下惡之，王因勿稱，以收天下，此大資也。", literal: "Qin adopts the title, the realm hates it—Your Majesty therefore should not adopt it, to win the realm; this is a great asset.", idiomatic: "Qin has taken the title and the world hates it—Your Majesty should therefore not take it, to win all under Heaven; this is a great advantage." },
  { zh: "且伐趙孰與伐桀宋利？", literal: "Moreover, is attacking Zhao or attacking tyrannical Song more profitable?", idiomatic: "Moreover, which is more profitable—attacking Zhao or attacking tyrannical Song?" },
  { zh: "今王不如釋帝以收天下之望，發兵以伐桀宋，宋舉則楚、趙、梁、衛皆懼矣。", literal: "Now Your Majesty would do better to relinquish the title of emperor to win the realm’s hopes, raise troops to attack tyrannical Song—when Song is taken, Chu, Zhao, Liang, and Wei will all be afraid.", idiomatic: "Now Your Majesty would do better to yield the imperial title and win the world’s goodwill, march against tyrannical Song—when Song falls, Chu, Zhao, Liang, and Wei will all fear you." },
  { zh: "是我以名尊秦而令天下憎之，所謂以卑為尊也。", literal: "This would be for us to honor Qin in name and make the realm hate it—what is called making the base the honored.", idiomatic: "That would honor Qin in name and make the world hate us—what they call treating the lowly as supreme." },
  { zh: "」齊王從之，稱帝二日而復歸之。", literal: "” The king of Qi followed this; he took the title of emperor for two days and then returned it.", idiomatic: "” The king of Qi agreed; he styled himself emperor for two days, then gave the title back." },
  { zh: "十二月，呂禮自齊入秦，秦王亦去帝復稱王。", literal: "Twelfth month: Lü Li came from Qi into Qin; the king of Qin also abandoned the title of emperor and again styled himself king.", idiomatic: "In the twelfth month Lü Li went from Qi to Qin; the king of Qin likewise dropped the imperial title and again styled himself king." },
  { zh: "2秦攻趙，拔杜陽。", literal: "2. Qin attacked Zhao and took Duyang.", idiomatic: "2. Qin attacked Zhao and seized Duyang." },
  { zh: "1秦攻〔魏〕(", literal: "1. Qin attacked [Wei] (", idiomatic: "1. Qin attacked [Wei] (" },
  { zh: "趙)", literal: "Zhao)", idiomatic: "Zhao)" },
  { zh: "，拔新垣、曲陽<ref>秦攻〔魏〕(", literal: ", and took Xinyuan and Quyang<ref>Qin attacked [Wei] (", idiomatic: ", and seized Xinyuan and Quyang<ref>Qin attacked [Wei] (" },
  { zh: "趙)", literal: "Zhao)", idiomatic: "Zhao)" },
  { zh: "拔新垣曲陽章校「十二行本『趙』作『魏』；", literal: "took Xinyuan and Quyang—Zhang’s collation: in the twelve-line edition “Zhao” reads “Wei”;", idiomatic: "took Xinyuan and Quyang—Zhang’s collation: in the twelve-line edition “Zhao” reads “Wei”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong’s edition agrees;", idiomatic: "Kong’s edition agrees;" },
  { zh: "張校同。", literal: "Zhang’s collation agrees.", idiomatic: "Zhang’s collation agrees." },
  { zh: "」《史記·趙世家》同，據改。", literal: "” The “House of Zhao” in the Records of the Grand Historian agrees—emended accordingly.", idiomatic: "” The “House of Zhao” in the Records agrees—emended accordingly." },
  { zh: "案：新垣、曲陽皆魏地，非趙地。", literal: "Note: Xinyuan and Quyang are both Wei territory, not Zhao territory.", idiomatic: "Note: Xinyuan and Quyang were both in Wei, not in Zhao." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1秦司馬錯擊魏河內。", literal: "1. Sima Cuo of Qin struck Wei’s Henei.", idiomatic: "1. Sima Cuo of Qin attacked Henei in Wei." },
  { zh: "魏獻安邑以和，秦出其人歸之魏。", literal: "Wei presented Anyi to make peace; Qin released the people there and returned them to Wei.", idiomatic: "Wei ceded Anyi to make peace; Qin released the inhabitants and sent them back to Wei." },
  { zh: "2秦敗韓師于夏山。", literal: "2. Qin defeated Han’s army at Mount Xia.", idiomatic: "2. Qin defeated the Han army at Mount Xia." },
  { zh: "3宋有雀生𪄟於城之陬。", literal: "3. In Song a sparrow gave birth to a hawk at a corner of the city wall.", idiomatic: "3. In Song a sparrow hatched a hawk at a corner of the city wall." },
  { zh: "史占之，曰：「吉。", literal: "The historiographer divined and said: “Auspicious.", idiomatic: "The historiographer divined and said: “Auspicious." },
  { zh: "小而生巨，必霸天下。", literal: "The small producing the great—you will surely dominate the realm.", idiomatic: "The small producing the great—you will surely dominate the realm." },
  { zh: "」宋康王喜，起兵滅滕；", literal: "” King Kang of Song rejoiced, raised troops and destroyed Teng;", idiomatic: "” King Kang of Song rejoiced, raised troops, and destroyed Teng;" },
  { zh: "伐薛；", literal: "attacked Xue;", idiomatic: "attacked Xue;" },
  { zh: "東敗齊，取五城；", literal: "in the east defeated Qi and took five cities;", idiomatic: "in the east defeated Qi and took five cities;" },
  { zh: "南敗楚，取地三百里，西敗魏軍。", literal: "in the south defeated Chu and took three hundred li of territory; in the west defeated Wei’s army.", idiomatic: "in the south defeated Chu and took three hundred li of territory; in the west defeated Wei’s army." },
  { zh: "與齊、魏為敵國，乃愈自信其霸。", literal: "He made enemies of Qi and Wei, and grew ever more confident in his hegemony.", idiomatic: "He made enemies of Qi and Wei and grew ever more confident in his hegemony." },
  { zh: "欲霸之亟成，故射天笞地，斬社稷而焚滅之，以示威服鬼神。", literal: "Wishing his hegemony to be quickly achieved, he shot at Heaven and whipped the earth, cut down the altars of soil and grain and burned them, to show his power and subdue spirits.", idiomatic: "Eager to complete his hegemony at once, he shot at Heaven, whipped the earth, destroyed the altars of soil and grain and burned them, to awe spirits and demons." },
  { zh: "為長夜之飲於室中，室中人呼萬歲，則堂上之人應之，堂下之人又應之，門外之人又應之，以至於國中，無敢不呼萬歲者。", literal: "He held night-long revels in his chamber; when those in the chamber cried “Long live the king!,” those in the hall answered; those below the hall answered again; those outside the gate answered again—extending through the state, none dared not cry “Long live the king!”", idiomatic: "He held all-night revels indoors; when those in the chamber shouted “Long live the king!,” those in the hall echoed; those below echoed again; those outside echoed again—through the whole state none dared not shout “Long live the king!”" },
  { zh: "天下之人謂之「桀宋」。", literal: "Men throughout the realm called him “tyrannical Song.”", idiomatic: "All under Heaven called him “tyrannical Song.”" },
  { zh: "齊湣王起兵伐之，民散，城不守。", literal: "King Min of Qi raised troops to attack him; the people scattered and the cities could not be held.", idiomatic: "King Min of Qi marched against him; the people scattered and the cities could not be defended." },
  { zh: "宋王奔魏，死於溫。", literal: "The king of Song fled to Wei and died at Wen.", idiomatic: "The king of Song fled to Wei and died at Wen." },
  { zh: "1秦王會楚王於宛，會趙王於中陽。", literal: "1. The king of Qin met the king of Chu at Wan and met the king of Zhao at Zhongyang.", idiomatic: "1. The king of Qin met the king of Chu at Wan and the king of Zhao at Zhongyang." },
  { zh: "2秦蒙武擊齊，拔九城。", literal: "2. Meng Wu of Qin attacked Qi and took nine cities.", idiomatic: "2. Meng Wu of Qin attacked Qi and seized nine cities." },
  { zh: "3齊湣王既滅宋而驕，乃南侵楚，西侵三晉，欲并二周，為天子。", literal: "3. King Min of Qi, having destroyed Song, grew arrogant; he then invaded Chu in the south, the Three Jins in the west, wished to annex the two Zhou domains, and become Son of Heaven.", idiomatic: "3. King Min of Qi, after destroying Song, grew arrogant; he invaded Chu in the south and the Three Jins in the west, sought to swallow the two Zhou capitals, and make himself Son of Heaven." },
  { zh: "狐咺正議，斫之檀衢，陳舉直言，殺之東閭。", literal: "Hu Hu offered straight counsel and was hewn apart at Tan Qu; Chen Ju spoke bluntly and was killed at Dong Lü.", idiomatic: "Hu Hu spoke forthrightly and was hacked to death at Tan Qu; Chen Ju spoke plainly and was executed at Dong Lü." },
  { zh: "燕昭王日夜撫循其人，益為富實，乃與樂毅謀伐齊。", literal: "King Zhao of Yan day and night comforted and guided his people, made them ever richer and stronger, and then joined Yue Yi in plotting to attack Qi.", idiomatic: "King Zhao of Yan day and night cared for his people, made the state ever richer and stronger, and plotted with Yue Yi to attack Qi." },
  { zh: "樂毅曰：「齊，霸國之餘業也。", literal: "Yue Yi said: “Qi retains the legacy of a hegemon state.", idiomatic: "Yue Yi said: “Qi retains the legacy of a hegemon state." },
  { zh: "地大人眾，未易獨攻也。", literal: "Its territory is large and its population many—not easy to attack alone.", idiomatic: "Its territory is large and its population many—not easy to attack alone." },
  { zh: "王必欲伐之。", literal: "If Your Majesty must attack it,", idiomatic: "If Your Majesty is determined to attack it," },
  { zh: "莫如約趙及楚、魏。", literal: "nothing is better than allying with Zhao as well as Chu and Wei.", idiomatic: "nothing is better than allying with Zhao, Chu, and Wei." },
  { zh: "」於是使樂毅約趙，別使使者連楚、魏，且令趙啖秦以伐齊之利。", literal: "” He thereupon sent Yue Yi to treat with Zhao, separately sent envoys to link Chu and Wei, and moreover had Zhao entice Qin with the profit of attacking Qi.", idiomatic: "” He sent Yue Yi to treat with Zhao, dispatched separate envoys to Chu and Wei, and had Zhao entice Qin with the gains of a campaign against Qi." },
  { zh: "諸侯害齊王之驕暴，皆爭合謀與燕伐齊。", literal: "The feudal lords resented King Min of Qi’s arrogance and violence; all vied to join in plotting with Yan to attack Qi.", idiomatic: "The feudal lords resented King Min’s arrogance and cruelty; all rushed to ally with Yan against Qi." },
  { zh: "1燕王悉起兵，以樂毅為上將軍。", literal: "1. The king of Yan mustered all troops and made Yue Yi supreme general.", idiomatic: "1. The king of Yan mobilized his entire army and made Yue Yi supreme general." },
  { zh: "秦尉斯離帥師與三晉之師會之。", literal: "Wei Sili, Qin’s commandant, led his army and joined the armies of the Three Jins.", idiomatic: "Wei Sili, Qin’s commandant, led his army to join the forces of the Three Jins." },
  { zh: "趙王以相國印授樂毅，樂毅並將秦、魏、韓、趙之兵以伐齊。", literal: "The king of Zhao gave Yue Yi the seal of chancellor; Yue Yi jointly commanded the armies of Qin, Wei, Han, and Zhao to attack Qi.", idiomatic: "The king of Zhao gave Yue Yi the chancellor’s seal; Yue Yi commanded the armies of Qin, Wei, Han, and Zhao against Qi." },
  { zh: "齊湣王悉國中之眾以拒之，戰於濟西，齊師大敗。", literal: "King Min of Qi mustered all within the state to resist; they fought west of the Ji River and Qi’s army was greatly defeated.", idiomatic: "King Min mobilized every man in Qi to resist; west of the Ji River the Qi army was routed." },
  { zh: "樂毅還秦、韓之師，分魏師以略宋地，部趙師以收河間，身率燕師，長驅逐北。", literal: "Yue Yi sent back the armies of Qin and Han, divided the Wei army to seize Song territory, assigned the Zhao army to recover Hejian, and himself led the Yan army in a long drive northward in pursuit.", idiomatic: "Yue Yi sent the Qin and Han armies home, detached the Wei force to seize Song lands, assigned the Zhao force to recover Hejian, and himself led the Yan army in a long pursuit north." },
  { zh: "劇辛曰：「齊大而燕小，賴諸侯之助以破其軍，宜及時攻取其邊城以自益，此長久之利也。", literal: "Ju Xin said: “Qi is great and Yan small; relying on the feudal lords’ help you broke their army—you should promptly attack and take border cities to enrich yourselves; this is a lasting profit.", idiomatic: "Ju Xin said: “Qi is great and Yan small; with the lords’ help you broke their army—you should seize border cities at once to strengthen yourselves; that is lasting gain." },
  { zh: "今過而不攻，以深入為名，無損於齊，無益於燕，而結深怨，後必悔之。", literal: "Now you pass cities without attacking, taking deep penetration as your reputation—no harm to Qi, no benefit to Yan, yet you forge deep enmity; later you will surely regret it.", idiomatic: "Now you march past cities without taking them, making a name for deep penetration—no harm to Qi, no gain for Yan, yet you forge deep hatred; you will regret it later." },
  { zh: "」樂毅曰：「齊王伐功矜能，謀不逮下，廢黜賢良，信任諂諛，政令戾虐，百姓怨懟。", literal: "” Yue Yi said: “The king of Qi boasts of achievements and flatters his abilities; his plans do not reach down to his subordinates; he deposes the worthy, trusts flatterers; his government orders are cruel and perverse, and the people resent and murmur.", idiomatic: "” Yue Yi said: “The king of Qi boasts of his feats and flatters his own talent; his counsel does not reach his subordinates; he dismisses the worthy and trusts sycophants; his edicts are cruel and perverse, and the people murmur in resentment." },
  { zh: "今軍皆破亡，若因而乘之，其民必叛，禍亂內作，則齊可圖也。", literal: "Now their army is all broken and destroyed—if we press the opportunity, its people are sure to rebel; disaster and turmoil arise within, and Qi can be taken.", idiomatic: "Now their army is destroyed—press the moment and the people will rebel; turmoil within will make Qi ripe for the taking." },
  { zh: "若不遂乘之，待彼悔前之非，改過恤下而撫其民，則難慮也。", literal: "If we do not press the advantage now, and wait until he repents his former faults, reforms and cares for his subordinates and comforts his people, then it will be hard to plan against.", idiomatic: "If we do not press now, and wait until he repents his faults, reforms, cares for his subordinates, and comforts his people, he will be hard to overcome." },
  { zh: "」遂進軍深入。", literal: "” He then advanced the army in depth.", idiomatic: "” He then drove the army deep into Qi." },
  { zh: "齊人果大亂失度，湣王出走。", literal: "The people of Qi indeed fell into great disorder and lost their bearings; King Min fled.", idiomatic: "The people of Qi fell into chaos; King Min fled." },
  { zh: "樂毅入臨淄，取寶物、祭器，輸之於燕。", literal: "Yue Yi entered Linzi, took treasures and ritual vessels, and sent them to Yan.", idiomatic: "Yue Yi entered Linzi, took treasures and ritual vessels, and sent them to Yan." },
  { zh: "燕王親至濟上勞軍，行賞饗士，封樂毅為昌國君，遂使留徇齊城之未下者。", literal: "The king of Yan personally came to the Ji River to comfort the army, bestowed rewards and feasted the soldiers, enfeoffed Yue Yi as lord of Changguo, and then had him remain to reduce Qi’s cities not yet taken.", idiomatic: "The king of Yan came in person to the Ji to review the troops, rewarded and feasted the army, enfeoffed Yue Yi as lord of Changguo, and left him to reduce the Qi cities still holding out." },
  { zh: "齊王出亡之衛，衛君辟宮舍之，稱臣而共具。", literal: "The king of Qi went out in exile to Wei; the lord of Wei vacated a palace to lodge him, styled himself minister, and shared provisions.", idiomatic: "The king of Qi fled to the state of Wei; its ruler vacated a palace for him, styled himself a minister, and shared his table." },
  { zh: "齊王不遜，衛人侵之。", literal: "The king of Qi was insolent; the people of Wei attacked him.", idiomatic: "The king of Qi was insolent; the men of Wei attacked him." },
  { zh: "齊王去奔鄒、魯，有驕色，鄒、魯弗內，遂走莒。", literal: "The king of Qi left and fled to Zou and Lu; he had a proud demeanor, and Zou and Lu would not admit him; he then fled to Ju.", idiomatic: "The king of Qi left for Zou and Lu with a proud bearing; neither state would admit him, and he fled to Ju." },
  { zh: "楚使淖齒將兵救齊，因為齊相。", literal: "Chu sent Nao Chi to lead troops to rescue Qi and thereby became Qi’s chancellor.", idiomatic: "Chu sent Nao Chi with an army to rescue Qi and made him Qi’s chancellor." },
  { zh: "淖齒欲與燕分齊地，乃執湣王而數之曰：「千乘、博昌之間，方數百里，雨血沾衣，王知之乎？", literal: "Nao Chi wished to divide Qi’s territory with Yan; he thereupon seized King Min and reckoned his crimes, saying: “Between the domain of a thousand chariots and Bochang, for several hundred li, rain of blood soaked garments—did Your Majesty know this?", idiomatic: "Nao Chi wished to divide Qi’s lands with Yan; he seized King Min and recounted his crimes: “Between your thousand-chariot realm and Bochang, over hundreds of li, blood rained and soaked garments—did Your Majesty know?" },
  { zh: "」曰：「知之。", literal: "” He said: “I knew it.", idiomatic: "” He said: “I knew it." },
  { zh: "」「贏、博之間，地坼及泉，王知之乎？", literal: "”“Between Ying and Bo, the earth split to the springs—did Your Majesty know this?", idiomatic: "”“Between Ying and Bo the earth split to the springs—did Your Majesty know?" },
  { zh: "」曰：「知之。", literal: "” He said: “I knew it.", idiomatic: "” He said: “I knew it." },
  { zh: "」「有人當闕而哭者，求之不得，去則聞其聲，王知之乎？", literal: "”“There was one who stood at the gate and wept; sought, he could not be found; when one left, his voice was heard—did Your Majesty know this?", idiomatic: "”“Someone wept at the gate; sought, he could not be found; when you left, you still heard his voice—did Your Majesty know?" },
  { zh: "」曰：「知之。", literal: "” He said: “I knew it.", idiomatic: "” He said: “I knew it." },
  { zh: "」淖齒曰：「天雨血沾衣者，天以告也；", literal: "” Nao Chi said: “When Heaven rains blood that soaks garments, Heaven is informing you;", idiomatic: "” Nao Chi said: “When Heaven rains blood that soaks garments, Heaven is warning you;" },
  { zh: "地坼及泉者，地以告也；", literal: "when the earth splits to the springs, the earth is informing you;", idiomatic: "when the earth splits to the springs, Earth is warning you;" },
  { zh: "有人當闕而哭者，人以告也。", literal: "when one stands at the gate and weeps, men are informing you.", idiomatic: "when someone weeps at the gate, men are warning you." },
  { zh: "天、地、人皆告矣，而王不知誡焉，何得無誅！", literal: "Heaven, earth, and men have all informed you, yet Your Majesty did not heed and warn yourself—how can you escape execution!", idiomatic: "Heaven, Earth, and men have all warned you, yet Your Majesty would not repent—how can you escape punishment!" },
  { zh: "」遂弒王於鼓里。", literal: "” He thereupon assassinated the king at Guli.", idiomatic: "” He then assassinated the king at Guli." },
  { zh: "荀子論之曰：國者，天下之利勢也。", literal: "Xunzi discussed it, saying: The state is the profit and power of the realm.", idiomatic: "Xunzi commented: The state is the profit and power of the realm." },
  { zh: "得道以持之，則大安也，大榮也，積美之源也。", literal: "Hold it by the Way and there is great security, great glory—the source of accumulated excellence.", idiomatic: "Held by the Way, it brings great security and great glory—the source of accumulated excellence." },
  { zh: "不得道以持之，則大危也，大累也，有之不如無之。", literal: "Fail to hold it by the Way and there is great peril, great burden—having it is not as good as not having it.", idiomatic: "Held without the Way, it brings great peril and great burden—better not to have it at all." },
  { zh: "及其綦也，索為匹夫，不可得也。", literal: "When it reaches the extreme, to seek to be a common man is impossible.", idiomatic: "At the extreme, one cannot even become a common man." },
  { zh: "齊湣、宋獻是也。", literal: "King Min of Qi and King Xian of Song were such cases.", idiomatic: "King Min of Qi and King Xian of Song are examples." },
  { zh: "故用國者義立而王，信立而霸，權謀立而亡。", literal: "Thus one who uses the state: when righteousness is established, he becomes king; when trust is established, he becomes hegemon; when schemes of power are established, he perishes.", idiomatic: "Thus for one who wields a state: establish righteousness and you may become king; establish trust and you may become hegemon; establish schemes of power and you perish." },
  { zh: "挈國以呼禮義也，而無以害之。", literal: "Take up the state to call forth ritual and righteousness, and nothing can harm it.", idiomatic: "Take up the state to proclaim ritual and righteousness, and nothing can harm it." },
  { zh: "行一不義，殺一無罪，而得天下，仁者不為也。", literal: "To perform one unrighteous act, kill one innocent man, and gain the realm—the benevolent do not do this.", idiomatic: "To commit one injustice, kill one innocent man, and win the realm—the benevolent will not do it." },
  { zh: "擽然扶持心國，且若是其固也。", literal: "With ardent effort uphold the state in one’s heart, and it is thus firm.", idiomatic: "Uphold the state wholeheartedly with ardent effort, and it is firm indeed." },
  { zh: "之所與為之者之人，則舉義士也；", literal: "Those with whom one acts are wholly men of righteousness;", idiomatic: "Those with whom one associates are wholly men of righteousness;" },
  { zh: "之所以為布陳於國家刑法者，則舉義法也；", literal: "what one deploys as law and punishment throughout the state is wholly righteous law;", idiomatic: "the laws and punishments one deploys throughout the state are wholly righteous law;" },
  { zh: "主之所極然，帥群臣而首向之者，則舉義志也。", literal: "what the ruler aims at utterly, leading his ministers and turning to face first, is wholly righteous purpose.", idiomatic: "what the ruler aims at utterly, leading his ministers to face first, is wholly righteous purpose." },
  { zh: "如是，則下仰上以義矣，是〔綦〕(", literal: "If so, then those below look up to those above through righteousness—this is [utterly] (", idiomatic: "If so, those below look up through righteousness—this is [the foundation] (" },
  { zh: "基)", literal: "foundation)", idiomatic: "foundation)" },
  { zh: "定也<ref>是〔綦〕(", literal: "established<ref>this is [utterly] (", idiomatic: "established<ref>this is [utterly] (" },
  { zh: "基)", literal: "foundation)", idiomatic: "foundation)" },
  { zh: "定也據《荀子·王霸篇》改，下同。", literal: "established emended per the “King and Hegemon” chapter of the Xunzi; the same below.", idiomatic: "established emended per the “King and Hegemon” chapter of Xunzi; the same below." },
  { zh: "「綦」，極也。", literal: "“Utterly” means “to the utmost.”", idiomatic: "“Utterly” means “to the utmost.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "〔綦〕(", literal: "[Utterly] (", idiomatic: "[Utterly] (" },
  { zh: "基)", literal: "foundation)", idiomatic: "foundation)" },
  { zh: "定而國定，國定而天下定。", literal: "When the foundation is established, the state is established; when the state is established, the realm is established.", idiomatic: "When the foundation is firm, the state is firm; when the state is firm, the realm is firm." },
  { zh: "故曰：以國濟義，一日而白，湯、武是也。", literal: "Thus it is said: use the state to complete righteousness, and in one day you are made clear—Tang and Wu were such.", idiomatic: "Thus it is said: use the state to fulfill righteousness, and in a day you shine forth—Tang and Wu did so." },
  { zh: "是所謂義立而王也。", literal: "This is what is called establishing righteousness and becoming king.", idiomatic: "This is what is called establishing righteousness and becoming king." },
  { zh: "德雖未至也，義雖未濟也，然而天下之理略奏矣，刑賞已諾信乎天下矣，臣下曉然皆知其可要也。", literal: "Though virtue has not yet arrived and righteousness has not yet been completed, yet the principles of the realm are roughly achieved; punishments and rewards have already been pledged and trusted by the realm; ministers and subordinates clearly all know what is essential.", idiomatic: "Though virtue is not yet complete and righteousness not yet fulfilled, the principles of the realm are roughly in place; punishments and rewards are pledged and trusted throughout the realm; ministers clearly know what matters." },
  { zh: "政令已陳，雖睹利敗，不欺其民；", literal: "Government orders have been proclaimed; though one sees profit fail, one does not deceive the people;", idiomatic: "Edicts have been proclaimed; though profit fails, one does not deceive the people;" },
  { zh: "約結已定，雖睹利敗，不欺其與。", literal: "Covenant bonds are already fixed; though one sees profit fail, one does not cheat one's allies.", idiomatic: "Once covenants are set, even when profit fails, one does not cheat one's allies." },
  { zh: "如是，則兵勁城固，敵國畏之；", literal: "If so, then troops are strong and walls firm, and enemy states fear one;", idiomatic: "Then arms are keen and walls secure, and enemy states fear you;" },
  { zh: "國一綦明，與國信之。", literal: "the state is unified and utmost clarity prevails, and allied states trust it.", idiomatic: "the state is united and utterly clear, and allied states trust it." },
  { zh: "雖在僻陋之國，威動天下，五伯是也。", literal: "Though in a remote and mean state, its awesomeness shakes all under Heaven—the Five Hegemons were such.", idiomatic: "Though seated in a remote and poor state, their might shook the realm—the Five Hegemons were such." },
  { zh: "是所謂信立而而霸也。", literal: "This is what is called establishing trust and becoming hegemon.", idiomatic: "This is what is called establishing trust and achieving hegemony." },
  { zh: "挈國以呼功利，不務張其義，齊其信，唯利之求；", literal: "To lead the state crying out for profit and utility, not striving to spread righteousness, align trustworthiness, seeking only profit;", idiomatic: "To lead the state in shouting for profit, not striving to spread righteousness or align trust, seeking only gain;" },
  { zh: "內則不憚詐其民而求小利焉，外則不憚詐其與而求大利焉。", literal: "inwardly not shrinking from deceiving one's people to seek small profit, outwardly not shrinking from deceiving one's allies to seek great profit.", idiomatic: "inwardly not hesitating to cheat one's people for small gain, outwardly not hesitating to cheat one's allies for great gain." },
  { zh: "內不修正其所以有，然常欲人之有，如是，則臣下百姓莫不以詐心待其上矣。", literal: "Inwardly not correcting what one possesses, yet constantly desiring what others possess—if so, then ministers and common folk all treat their superiors with deceit in heart.", idiomatic: "Inwardly not setting right what one already has, yet always coveting what others hold—then ministers and people alike meet their superiors with deceit in heart." },
  { zh: "上詐其下，下詐其上，則是上下析也。", literal: "Superiors deceive subordinates, subordinates deceive superiors—then above and below are sundered.", idiomatic: "Superiors cheat subordinates, subordinates cheat superiors—then above and below are split apart." },
  { zh: "如是，則敵國輕之，與國疑之，權謀日行而國不免危削，綦之而亡，齊湣、薛公是也。", literal: "If so, enemy states despise one, allied states doubt one, plots and schemes practiced daily yet the state cannot escape peril and diminution, at the utmost it perishes—King Min of Qi and Lord Xue were such.", idiomatic: "Then enemy states despise you, allies doubt you, stratagems multiply daily yet the state cannot escape danger and shrinkage, and at the extreme it perishes—King Min of Qi and Lord Xue were such." },
  { zh: "故用強齊，非以修禮義也，非以本政教也，非以一天下也，綿綿常以結引馳外為務。", literal: "Thus employing mighty Qi was not to cultivate rites and righteousness, not to root government and teaching, not to unify all under Heaven; constantly and ceaselessly making bonding and drawing abroad the task of galloping outward.", idiomatic: "Thus the use of mighty Qi was not to cultivate rites and righteousness, not to ground government and teaching, not to unify the realm—it constantly made alliance-building and outward campaigning its business." },
  { zh: "故強，南足以破楚，西足以詘秦，北足以敗燕，中足以舉宋。", literal: "Hence when strong: south sufficient to break Chu, west sufficient to humble Qin, north sufficient to defeat Yan, central sufficient to overthrow Song.", idiomatic: "When it was strong, south it could break Chu, west humble Qin, north defeat Yan, and in the center overthrow Song." },
  { zh: "及以燕、趙起而攻之，若振槁然，而身死國亡，為天下大戮，後世言惡則必稽焉。", literal: "When Yan and Zhao rose to attack it, it was like shaking dry stalks; yet body perished and state was lost, becoming a great disgrace under Heaven—later ages speaking of evil must cite it.", idiomatic: "When Yan and Zhao rose against it, Qi fell like shaken dry stalks—yet its ruler died and its state perished, a great shame under Heaven; later ages naming evil must cite it." },
  { zh: "是無他故焉，唯其不由禮義而由權謀也。", literal: "This has no other reason—only that it did not proceed by rites and righteousness but by plots and schemes.", idiomatic: "There is no other cause—only that it followed not rites and righteousness but plots and schemes." },
  { zh: "三者，明主之所謹擇也，仁人之所務白也。", literal: "These three paths—a wise lord carefully chooses among them; a humane person makes it his business to clarify them.", idiomatic: "These three courses a wise ruler carefully chooses; a humane man labors to make them clear." },
  { zh: "善擇者制人，不善擇者人制之。", literal: "Those who choose well control others; those who choose poorly are controlled by others.", idiomatic: "Those who choose well control others; those who choose poorly are controlled by others." },
  { zh: "2樂毅聞〔畫〕(", literal: "2 Yue Yi heard that in 〔Hua〕(", idiomatic: "2 Yue Yi heard that in 〔Hua〕(" },
  { zh: "晝)", literal: "晝)", idiomatic: "晝)" },
  { zh: "邑人王蠋賢<ref>樂毅聞〔畫〕(", literal: "the townsman Wang Zhu was worthy<ref>Yue Yi heard that in 〔Hua〕(", idiomatic: "the townsman Wang Zhu was worthy<ref>Yue Yi heard that in 〔Hua〕(" },
  { zh: "晝)", literal: "晝)", idiomatic: "晝)" },
  { zh: "邑人王蠋賢章校「十二行本『晝』作『畫』；", literal: "the townsman Wang Zhu was worthy—Zhang's collation: the twelve-line edition reads 晝 as 畫;", idiomatic: "the townsman Wang Zhu was worthy—Zhang's collation: the twelve-line edition reads 晝 as 畫;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "下均同。", literal: "below all agree.", idiomatic: "below all agree." },
  { zh: "」據改。", literal: "” amended accordingly.", idiomatic: "” amended accordingly." },
  { zh: "</ref>，令軍中環〔畫〕(", literal: "</ref>, and ordered the army to encircle 〔Hua〕(", idiomatic: "</ref>, and ordered the army to encircle 〔Hua〕(" },
  { zh: "晝)", literal: "晝)", idiomatic: "晝)" },
  { zh: "邑三十里無入。", literal: "the town for thirty li, allowing no entry within.", idiomatic: "the town for thirty li, with no one permitted to enter." },
  { zh: "使人請蠋，蠋謝不往。", literal: "He sent someone to invite Zhu; Zhu declined and did not go.", idiomatic: "He sent to invite Zhu; Zhu declined and would not come." },
  { zh: "燕人曰：「不來，吾且屠〔畫〕(", literal: "The men of Yan said: “If you do not come, we shall slaughter 〔Hua〕(", idiomatic: "The men of Yan said: “If you do not come, we shall slaughter 〔Hua〕(" },
  { zh: "晝)", literal: "晝)", idiomatic: "晝)" },
  { zh: "邑！", literal: "the town!", idiomatic: "the town!”" },
  { zh: "」蠋曰：「忠臣不事二君，烈女不更二夫。", literal: "” Zhu said: “A loyal minister does not serve two lords; a chaste woman does not take a second husband.", idiomatic: "” Zhu said: “A loyal minister does not serve two lords; a steadfast woman does not take a second husband." },
  { zh: "〔齊王不用吾諫，故退而耕於野〕<ref>〔齊王不用吾諫，故退而耕於野〕章校「十二行本『夫』下有『齊王不用吾諫故退而耕於野』十二字；", literal: "〔The king of Qi did not employ my remonstrance, so I withdrew and farmed in the wilds〕<ref>〔The king of Qi did not employ my remonstrance, so I withdrew and farmed in the wilds〕—Zhang's collation: the twelve-line edition after “husband” has the twelve characters “The king of Qi did not employ my remonstrance, so I withdrew and farmed in the wilds”;", idiomatic: "〔The king of Qi would not heed my counsel, so I withdrew to farm in the wilds〕<ref>〔The king of Qi would not heed my counsel, so I withdrew to farm in the wilds〕—Zhang's collation: the twelve-line edition after “husband” has the twelve characters “The king of Qi would not heed my counsel, so I withdrew to farm in the wilds”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同；", literal: "Zhang's collation agrees;", idiomatic: "Zhang's collation agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai's collation agrees.", idiomatic: "Tui Zhai's collation agrees." },
  { zh: "」據補。", literal: "” supplemented accordingly.", idiomatic: "” supplemented accordingly." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "國破君亡，吾不能存，而又欲劫之以兵，吾與其不義而生，不若死！", literal: "The state is destroyed and the lord perished—I cannot preserve them; yet you would coerce me with arms. I would rather die than live without righteousness!", idiomatic: "The state is ruined and the lord dead—I could not save them; now you would force me at sword-point. Better die than live without righteousness!" },
  { zh: "」遂經其頸於樹枝，自奮絕脰而死。", literal: "” He thereupon looped a cord about his neck on a tree branch and, straining, broke his neck and died.", idiomatic: "” He looped a cord about his neck on a branch and, straining, broke his neck and died." },
  { zh: "燕師乘勝長驅，齊城皆望風奔潰。", literal: "Yan troops pressed the victory in long pursuit; Qi cities all fled before the wind in rout.", idiomatic: "Yan armies pressed the victory in long pursuit; Qi cities everywhere fled at the rumor of their coming." },
  { zh: "樂毅修整燕軍，禁止侵掠，求齊之逸民，顯而禮之。", literal: "Yue Yi put the Yan army in order, forbade pillage, sought Qi’s scattered people, and honored and treated them with rites.", idiomatic: "Yue Yi disciplined the Yan army, forbade looting, sought out Qi’s displaced people, and honored them with ceremony." },
  { zh: "寬其賦斂，除其暴令，修其舊政<ref>修其舊政章校「孔本『政』作『制』。", literal: "He eased their levies, removed their harsh orders, and restored their old government<ref>Restore their old government—Zhang's collation: Kong’s edition reads 政 as 制.", idiomatic: "He eased their taxes, removed harsh edicts, and restored their old institutions<ref>Restore their old institutions—Zhang's collation: Kong’s edition reads 政 as 制." },
  { zh: "」案：二字均可。", literal: "” Note: both characters are acceptable.", idiomatic: "” Note: both readings are acceptable." },
  { zh: "</ref>，齊民喜悅。", literal: "</ref>, and the people of Qi rejoiced.", idiomatic: "</ref>, and the people of Qi rejoiced." },
  { zh: "乃遣左軍渡膠東、東萊；", literal: "He then sent the left army across Jiaodong and Donglai;", idiomatic: "He sent the left army across Jiaodong and Donglai;" },
  { zh: "前軍循太山以東至海，略琅邪；", literal: "the vanguard followed Mount Tai east to the sea and overran Langye;", idiomatic: "the vanguard followed Mount Tai east to the sea and seized Langye;" },
  { zh: "右軍循河、濟，屯阿、鄄以連魏師；", literal: "the right army followed the Yellow River and Ji, encamped at A and Juancheng to link with Wei’s troops;", idiomatic: "the right army followed the Yellow River and Ji, encamped at A and Juancheng to join Wei’s army;" },
  { zh: "後軍旁北海以撫千乘；", literal: "the rear army skirted the northern sea to pacify Qiancheng;", idiomatic: "the rear army skirted the northern sea to secure Qiancheng;" },
  { zh: "中軍據臨淄而鎮齊都。", literal: "the center army held Linzi and stabilized the Qi capital.", idiomatic: "the center army held Linzi and secured the Qi capital." },
  { zh: "祀桓公、管仲於郊，表賢者之閭，封王蠋之墓。", literal: "He sacrificed to Duke Huan and Guan Zhong in the suburbs, marked the lanes of worthy men, and enfeoffed Wang Zhu’s tomb.", idiomatic: "He sacrificed to Duke Huan and Guan Zhong in the suburbs, marked the neighborhoods of worthy men, and enfeoffed Wang Zhu’s tomb." },
  { zh: "齊人食邑於燕者二十餘君，有爵位於薊者百有餘人。", literal: "Men of Qi receiving fiefs in Yan numbered more than twenty lords; those holding ranks in Ji numbered more than a hundred.", idiomatic: "More than twenty Qi men held fiefs in Yan; more than a hundred held titles in Ji." },
  { zh: "六月之間，下齊七十餘城，皆為郡縣。", literal: "Within six months he reduced more than seventy cities of Qi, all made into commanderies and counties.", idiomatic: "Within six months he took more than seventy Qi cities, all made into commanderies and counties." },
  { zh: "3秦王、魏王、韓王會于京師。", literal: "3 The king of Qin, the king of Wei, and the king of Han met at the capital.", idiomatic: "3 The kings of Qin, Wei, and Han met at the capital." },
  { zh: "1秦、趙會于穰。", literal: "1 Qin and Zhao met at Rang.", idiomatic: "1 Qin and Zhao met at Rang." },
  { zh: "秦拔魏安城，兵至大梁而還。", literal: "Qin took Ancheng of Wei; its troops reached Daliang and returned.", idiomatic: "Qin took Wei’s Ancheng, marched to Daliang, and withdrew." },
  { zh: "2齊淖齒之亂，湣王子法章變名姓為莒太史敫家傭。", literal: "2 In the turmoil of Nao Chi in Qi, Min’s son Fajiu changed his name and surname and became a hired man in the household of the Grand Historian of Ju, Jiao.", idiomatic: "2 In the turmoil of Nao Chi in Qi, King Min’s son Fajiu changed his name and worked as a hired hand in the household of Ju’s Grand Historian, Jiao." },
  { zh: "太史敫女奇法章狀貌，以為非常人，憐而常竊衣食之，因與私通。", literal: "Jiao’s daughter marveled at Fajiu’s appearance, thought him no ordinary man, pitied him and often secretly gave him food and clothing, and thereby had relations with him in private.", idiomatic: "Jiao’s daughter was struck by Fajiu’s looks, judged him no ordinary man, pitied him and often secretly fed and clothed him, and came to know him intimately." },
  { zh: "王孫賈從湣王，失王之處，其母曰：「汝朝出而晚來，則吾倚門而望；", literal: "Wangsun Jia had followed King Min and lost track of the king’s whereabouts. His mother said: “When you went out in the morning and came back late, I leaned on the door and looked;", idiomatic: "Wangsun Jia had followed King Min and lost track of him. His mother said: “When you went out in the morning and came back late, I leaned on the door and watched;" },
  { zh: "汝暮出而不還，則吾倚閭而望。", literal: "when you went out at dusk and did not return, I leaned on the lane-end and looked.", idiomatic: "when you went out at dusk and did not return, I leaned on the lane-end and watched." },
  { zh: "汝今事王，王走，汝不知其處，汝尚何歸焉！", literal: "Now you serve the king; the king has fled and you do not know where he is—where can you still return!", idiomatic: "Now you serve the king; the king has fled and you do not know where—where can you still return!”" },
  { zh: "」王孫賈乃入市中呼曰：「淖齒亂齊國，殺湣王。", literal: "” Wangsun Jia then went into the market and cried: “Nao Chi threw Qi into turmoil and killed King Min.", idiomatic: "” Wangsun Jia went into the market and cried: “Nao Chi threw Qi into turmoil and killed King Min." },
  { zh: "欲與我誅之者袒右！", literal: "Who wishes to join me in executing him, bare your right shoulder!", idiomatic: "Who will join me in killing him, bare your right shoulder!”" },
  { zh: "」市人從者四百人，與攻淖齒，殺之。", literal: "” Four hundred men of the market followed him; together they attacked Nao Chi and killed him.", idiomatic: "” Four hundred marketmen followed; together they attacked Nao Chi and killed him." },
  { zh: "於是齊亡臣相與求湣王子，欲立之。", literal: "Thereupon Qi’s exiled ministers together sought King Min’s son, wishing to install him.", idiomatic: "Then Qi’s exiled ministers together sought King Min’s son, intending to set him on the throne." },
  { zh: "法章懼其誅己，久之乃敢自言，遂立以為齊王，保莒城以拒燕，佈告國中曰：「王已立在莒矣！", literal: "Fajiu feared they would execute him; only after a long time did he dare reveal himself. They thereupon installed him as king of Qi, held Ju city to resist Yan, and proclaimed throughout the state: “The king has already been installed at Ju!", idiomatic: "Fajiu feared they would kill him; only after long delay did he dare reveal himself. They installed him as king of Qi, held Ju to resist Yan, and proclaimed: “The king has been installed at Ju!”" },
  { zh: "3趙王得楚和氏璧，秦昭王欲之，請易以十五城。", literal: "3 The king of Zhao obtained the He Clan jade of Chu; King Zhao of Qin desired it and asked to exchange it for fifteen cities.", idiomatic: "3 The king of Zhao obtained Chu’s He Clan jade; King Zhao of Qin wanted it and offered fifteen cities in exchange." },
  { zh: "趙王欲勿與，畏秦強，欲與之，恐見欺。", literal: "The king of Zhao wished not to give it, yet feared Qin’s strength; wished to give it, yet feared being deceived.", idiomatic: "The king of Zhao wished to refuse, yet feared Qin’s might; wished to yield it, yet feared being cheated." },
  { zh: "以問藺相如，對曰：「秦以城求璧而王不許，曲在我矣；", literal: "He asked Lin Xiangru, who replied: “If Qin asks for the jade with cities and Your Majesty does not agree, the wrong is on our side;", idiomatic: "He asked Lin Xiangru, who answered: “If Qin offers cities for the jade and Your Majesty refuses, the fault is ours;" },
  { zh: "我與之璧而秦不與我城，則曲在秦。", literal: "if we give the jade and Qin does not give us cities, then the wrong is on Qin’s side.", idiomatic: "if we give the jade and Qin withholds the cities, the fault is Qin’s." },
  { zh: "均之二策，寧許以負秦。", literal: "Weighing the two plans, it is better to agree and lay the blame on Qin.", idiomatic: "Between the two courses, better agree and put the blame on Qin." },
  { zh: "臣願奉璧而往；", literal: "Your servant wishes to carry the jade and go;", idiomatic: "I will carry the jade there;" },
  { zh: "使秦城不入，臣請完璧而歸之。", literal: "if Qin’s cities do not come in, your servant begs to return the jade intact.", idiomatic: "if the cities are not delivered, I will return the jade intact.”" },
  { zh: "」趙王遣之。", literal: "” The king of Zhao sent him.", idiomatic: "” The king of Zhao sent him." },
  { zh: "相如至秦，秦王無意償趙城。", literal: "Xiangru arrived in Qin; the king of Qin had no intention of paying Zhao with cities.", idiomatic: "Xiangru reached Qin; the king of Qin had no intention of yielding the cities." },
  { zh: "相如乃以詐紿秦王，復取璧，遣從者懷之，間行歸趙，而以身待命於秦。", literal: "Xiangru then used deceit to beguile the king of Qin, took back the jade, sent a follower to carry it concealed, and by secret route returned to Zhao, while he himself awaited punishment in Qin.", idiomatic: "Xiangru then deceived the king of Qin, recovered the jade, sent a follower to carry it home by a secret route, and himself remained in Qin to await punishment." },
  { zh: "秦王以為賢而弗誅，禮而歸之。", literal: "The king of Qin thought him worthy and did not execute him, but treated him with courtesy and sent him home.", idiomatic: "The king of Qin judged him worthy and did not punish him, but honored him and sent him home." },
  { zh: "趙王以相如為上大夫。", literal: "The king of Zhao made Xiangru Grand Master.", idiomatic: "The king of Zhao made Xiangru a grand master." },
  { zh: "4衛嗣君薨，子懷君立。", literal: "4 Lord Successor of Wei died; his son Lord Huai succeeded.", idiomatic: "4 Lord Successor of Wei died; his son Lord Huai succeeded." },
  { zh: "嗣君好察微隱，縣令有發褥而席敝者，嗣君聞之，乃賜之席。", literal: "Lord Successor loved to scrutinize minute and hidden matters. A district magistrate had worn out his mat by pulling up the bedding; when Lord Successor heard of it, he bestowed a mat upon him.", idiomatic: "Lord Successor loved to detect minute secrets. A magistrate had worn through his mat by turning his bedding; when Lord Successor heard, he sent him a new mat." },
  { zh: "令大驚，以君為神。", literal: "The magistrate was greatly alarmed and took his lord for divine.", idiomatic: "The magistrate was terrified and took his lord for a god." },
  { zh: "又使人過關市，賂之以金，既而召關市，問有客過與汝金，汝回遣之，關市大恐。", literal: "He also sent someone through the market gate, bribing the gate officer with gold; shortly afterward he summoned the gate officer and asked whether a traveler had passed and given him gold, and whether he had sent it back—the gate officer was greatly terrified.", idiomatic: "He also sent a man through the market gate to bribe the gate officer with gold; then he summoned the officer and asked whether a traveler had given him gold and whether he had returned it—the officer was terrified." },
  { zh: "又愛洩姬，重如耳，而恐其因愛重以壅己也，乃貴薄疑以敵如耳，尊魏妃以偶泄姬，曰：「以是相參也。", literal: "He also loved Lady Xie and favored Ru Er, yet feared that through love and favor they might block him; he therefore exalted Bo Yi to match Ru Er and honored the Wei consort to pair with Lady Xie, saying: “Thus they check one another.", idiomatic: "He also favored Lady Xie and prized Ru Er, yet feared they might use favor to hem him in; he therefore elevated Bo Yi to rival Ru Er and honored the Wei consort to balance Lady Xie, saying: “Let them check one another." },
  { zh: "荀子論之曰：成侯、嗣君，聚斂計數之君也，未及取民也。", literal: "Xunzi discussed it, saying: Marquis Cheng and Lord Successor were lords who amassed wealth and reckoned accounts—they had not yet reached taking the people in hand.", idiomatic: "Xunzi remarked: Marquis Cheng and Lord Successor were rulers who hoarded wealth and counted accounts—they had not yet learned to win the people." },
  { zh: "子產，取民者也，未及為政也。", literal: "Zi Chan was one who took the people in hand—he had not yet reached governing.", idiomatic: "Zi Chan won the people—he had not yet reached true government." },
  { zh: "管仲，為政者也，未及修禮也。", literal: "Guan Zhong was one who governed—he had not yet reached cultivating rites.", idiomatic: "Guan Zhong governed—he had not yet reached cultivating rites." },
  { zh: "故修禮者王，為政者強，取民者安，聚斂者亡。", literal: "Thus those who cultivate rites become kings, those who govern become strong, those who take the people find security, those who amass and squeeze perish.", idiomatic: "Thus those who cultivate rites become kings, those who govern grow strong, those who win the people find security, and those who hoard perish." },
  { zh: "1秦伐趙，拔兩城。", literal: "1 Qin attacked Zhao and took two cities.", idiomatic: "1 Qin attacked Zhao and took two cities." },
  { zh: "1秦伐趙，拔石城。", literal: "1 Qin attacked Zhao and took Shicheng.", idiomatic: "1 Qin attacked Zhao and took Shicheng." },
  { zh: "2秦穰侯復為丞相。", literal: "2 The Marquis of Rang of Qin again became chancellor.", idiomatic: "2 Qin’s Marquis of Rang again became chancellor." },
  { zh: "3楚欲與齊、韓共伐秦，因欲圖周。", literal: "3 Chu wished to join Qi and Han in attacking Qin, and thereby wished to scheme against Zhou.", idiomatic: "3 Chu wished to join Qi and Han in attacking Qin, and also meant to scheme against Zhou." },
  { zh: "王使東周武公謂楚令尹昭子曰：「周不可圖也。", literal: "The king sent the Martial Lord of Eastern Zhou to tell Zhao, chief minister of Chu: “Zhou cannot be schemed against.", idiomatic: "The king sent the Martial Lord of Eastern Zhou to tell Chu’s chief minister Zhao: “Zhou cannot be taken by plotting." },
  { zh: "」昭子曰：「乃圖周，則無之；", literal: "” Zhao said: “As for scheming against Zhou, there is none of that;", idiomatic: "” Zhao said: “As for plotting against Zhou, there is none of that;" },
  { zh: "雖然，何不可圖？", literal: "even so, why can it not be schemed against?", idiomatic: "even so, why can it not be plotted against?”" },
  { zh: "」武公曰：「西周之地，絕長補短，不過百里。", literal: "” The Martial Lord said: “The lands of Western Zhou, joined end to end and patched short with long, do not exceed a hundred li.", idiomatic: "” The Martial Lord said: “Western Zhou’s territory, end to end, does not exceed a hundred li." },
  { zh: "名為天下共主，裂其地不足以肥國，得其眾不足以勁兵。", literal: "In name it is the common lord of all under Heaven; to carve up its land is insufficient to enrich a state, to gain its people is insufficient to strengthen an army.", idiomatic: "In name it is lord of all under Heaven, yet carving its land would not enrich a state, nor would gaining its people strengthen an army." },
  { zh: "雖然，攻之者名為弒君。", literal: "Even so, those who attack it are named regicides.", idiomatic: "Even so, whoever attacks it will be called a regicide." },
  { zh: "然而猶有欲攻之者，見祭器在焉故也。", literal: "Yet still there are those who wish to attack it, because they see the sacrificial vessels are there.", idiomatic: "Yet some still wish to attack it—because they see the sacrificial vessels are there." },
  { zh: "夫虎肉臊而兵利身，人猶攻之；", literal: "Now tiger flesh is rank and its body bristles with sharp weapons, yet men still attack it;", idiomatic: "Tiger flesh is rank and its body bristles with weapons, yet men still attack it;" },
  { zh: "若使澤中之麋蒙虎之皮，人之攻之也必萬倍矣。", literal: "If a marsh deer were to wear a tiger's hide, men's attacking it would surely be ten thousandfold.", idiomatic: "If a marsh deer wore a tiger's hide, men would attack it ten thousand times over." },
  { zh: "裂楚之地，足以肥國；", literal: "To carve up Chu's lands would suffice to enrich the state;", idiomatic: "Splitting Chu's territory would enrich your state;" },
  { zh: "詘楚之名，足以尊〔主〕(", literal: "Checking Chu's name would suffice to exalt the 〔lord〕(", idiomatic: "Humbling Chu's renown would exalt the 〔lord〕(" },
  { zh: "王)", literal: "king)", idiomatic: "king)" },
  { zh: "<ref>足以尊〔主〕(", literal: "<ref>To exalt the 〔lord〕(", idiomatic: "<ref>To exalt the 〔lord〕(" },
  { zh: "王)", literal: "king)", idiomatic: "king)" },
  { zh: "章校「十二行本『王』作『主』；", literal: "Zhang's collation: “In the twelve-line edition ‘king’ reads ‘lord’;", idiomatic: "Zhang's collation: “In the twelve-line edition ‘king’ reads ‘lord’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai's collation agrees.", idiomatic: "Tui Zhai's collation agrees." },
  { zh: "」據改。", literal: "” emended accordingly.", idiomatic: "” emended accordingly." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "今子欲誅殘天下之共主，居三代之傳器，器南，則兵至矣。", literal: "Now you wish to slaughter the world's common lord, occupy the transmitted vessels of the Three Dynasties—set them facing south, and troops will arrive.", idiomatic: "Now you would slaughter the lord of all under Heaven, seize the regalia of the Three Dynasties, set them facing south—and armies will come." },
  { zh: "」於是楚計輟不行。", literal: "” Thereupon Chu's scheme was abandoned and not carried out.", idiomatic: "” Thereupon Chu's plan was dropped and not carried out." },
  { zh: "1秦白起敗趙軍，斬首二萬，取代光狼城。", literal: "1 Qin's Bai Qi defeated Zhao's army, beheaded twenty thousand, and took the city of Guanglang.", idiomatic: "1 Qin's Bai Qi defeated the army of Zhao, beheaded twenty thousand, and took Guanglang." },
  { zh: "又使司馬錯發隴西兵，因蜀攻楚黔中，拔之。", literal: "He also had Sima Cuo raise troops from Longxi, and through Shu attacked Chu's Qianzhong and seized it.", idiomatic: "He also had Sima Cuo raise Longxi troops and, via Shu, attack Chu's Qianzhong and take it." },
  { zh: "楚獻漢北及上庸地。", literal: "Chu offered the lands north of the Han and Shangyong.", idiomatic: "Chu yielded the territory north of the Han and Shangyong." },
  { zh: "1秦白起伐楚，取鄢、鄧、西陵。", literal: "1 Qin's Bai Qi attacked Chu and took Yan, Deng, and Xiling.", idiomatic: "1 Qin's Bai Qi attacked Chu and took Yan, Deng, and Xiling." },
  { zh: "2秦王使使者告趙王，願為好會於河外澠池。", literal: "2 The king of Qin sent an envoy to inform the king of Zhao that he wished to meet in friendship at Mianchi beyond the River.", idiomatic: "2 The king of Qin sent an envoy to the king of Zhao, proposing a friendly meeting at Mianchi beyond the River." },
  { zh: "趙王欲毋行，廉頗、藺相如計曰：「王不行，示趙弱且怯也。", literal: "The king of Zhao wished not to go; Lian Po and Lin Xiangru counselled, saying, “If Your Majesty does not go, it shows Zhao weak and cowardly.", idiomatic: "The king of Zhao wished not to go. Lian Po and Lin Xiangru advised: “If Your Majesty does not go, it shows Zhao weak and afraid." },
  { zh: "」趙王遂行，相如從。", literal: "” The king of Zhao then went, and Xiangru accompanied him.", idiomatic: "” The king of Zhao went, and Xiangru went with him." },
  { zh: "廉頗送至境，與王訣曰：「王行，度道里會遇之禮畢，還，不過三十日。", literal: "Lian Po escorted him to the border and took leave, saying, “When Your Majesty goes, estimating the distance and the rites of meeting, on return it will not exceed thirty days.", idiomatic: "Lian Po escorted him to the border and bade farewell: “When Your Majesty goes, reckon the road and the courtesies of the meeting—your return should take no more than thirty days." },
  { zh: "三十日不還，則請立太子，以絕秦望。", literal: "If thirty days pass without return, I beg to establish the crown prince, to cut off Qin's hopes.", idiomatic: "If you are not back in thirty days, I ask leave to install the crown prince and cut off Qin's hopes." },
  { zh: "」王許之。", literal: "” The king assented.", idiomatic: "” The king agreed." },
  { zh: "會于澠池。", literal: "They met at Mianchi.", idiomatic: "They met at Mianchi." },
  { zh: "〔秦〕王與趙王飲<ref>〔秦〕王與趙王飲據胡注補。", literal: "The 〔Qin〕 king and the king of Zhao drank<ref>The 〔Qin〕 king and the king of Zhao drank—supplemented per Hu's commentary.", idiomatic: "The 〔Qin〕 king and the king of Zhao drank<ref>The 〔Qin〕 king and the king of Zhao drank—supplemented per Hu's commentary." },
  { zh: "</ref>，酒酣，秦王請趙王鼓瑟，趙王鼓之。", literal: "</ref> When the wine was heated, the king of Qin asked the king of Zhao to play the se; the king of Zhao played.", idiomatic: "</ref> When the wine was warm, the king of Qin asked the king of Zhao to play the se, and the king of Zhao played." },
  { zh: "藺相如復請秦王擊缶，秦王不肯。", literal: "Lin Xiangru in turn asked the king of Qin to strike the fou; the king of Qin refused.", idiomatic: "Lin Xiangru in turn asked the king of Qin to strike the fou; the king of Qin refused." },
  { zh: "相如曰：「五步之內，臣請得以頸血濺大王矣！", literal: "Xiangru said, “Within five paces your servant begs leave to splash his neck-blood upon Your Majesty!", idiomatic: "Xiangru said, “Within five paces I beg leave to splash my blood on Your Majesty!" },
  { zh: "」左右欲刃相如，相如張目叱之，左右皆靡。", literal: "” Those at left and right wished to blade Xiangru; Xiangru glared and shouted them down, and all shrank away.", idiomatic: "” Attendants moved to kill Xiangru; he glared and shouted them down, and all shrank back." },
  { zh: "王不懌，為一擊缶。", literal: "The king was displeased but struck the fou once.", idiomatic: "The king was displeased but struck the fou once." },
  { zh: "罷酒，秦終不能有加於趙。", literal: "When the drinking ended, Qin in the end could do nothing more against Zhao.", idiomatic: "When the feast ended, Qin could do Zhao no further harm." },
  { zh: "趙人亦盛為之備，秦不敢動。", literal: "The men of Zhao had also made full preparations; Qin did not dare act.", idiomatic: "The men of Zhao had also made full preparations, and Qin did not dare move." },
  { zh: "趙王歸國，以藺相如為上卿，位在廉頗之右。", literal: "The king of Zhao returned to his state and made Lin Xiangru senior minister, ranking to Lian Po's right.", idiomatic: "The king of Zhao returned home, made Lin Xiangru senior minister, and ranked him above Lian Po." },
  { zh: "廉頗曰：「我為趙將，有攻城野戰之功。", literal: "Lian Po said, “I am Zhao's general and have merit in storming cities and field battles.", idiomatic: "Lian Po said, “I am Zhao's general. I have merit in storming cities and fighting in the field." },
  { zh: "藺相如素賤人，徒以口舌而位居我上。", literal: "Lin Xiangru was always a low fellow who by words alone ranks above me.", idiomatic: "Lin Xiangru was always a nobody who ranks above me on words alone." },
  { zh: "吾羞，不忍為之下！", literal: "I am ashamed and cannot bear to rank below him!", idiomatic: "I am ashamed and cannot bear to stand below him!" },
  { zh: "」宣言曰：「我見相如，必辱之！", literal: "” He declared, “When I see Xiangru I will surely humiliate him!", idiomatic: "” He declared, “When I see Xiangru I will humiliate him!" },
  { zh: "」相如聞之，不肯與會；", literal: "” Xiangru heard this and refused to meet him;", idiomatic: "” Xiangru heard and refused to meet him;" },
  { zh: "每朝，常稱病，不欲爭列。", literal: "at each court session he often pleaded illness and did not wish to contend for rank.", idiomatic: "at court he often pleaded illness and would not vie for precedence." },
  { zh: "出而望見，輒引車避匿。", literal: "When he went out and saw him in the distance, he would turn his carriage aside to avoid him.", idiomatic: "When he went out and saw him afar, he would turn his carriage aside to avoid him." },
  { zh: "其舍人皆以為恥。", literal: "His retainers all regarded this as shameful.", idiomatic: "His retainers all thought this shameful." },
  { zh: "相如曰：「子視廉將軍孰與秦王？", literal: "Xiangru said, “In your view, how does General Lian compare to the king of Qin?", idiomatic: "Xiangru said, “How does General Lian compare with the king of Qin, in your view?" },
  { zh: "」曰：「不若。", literal: "” They said, “Not equal.", idiomatic: "” They said, “He does not." },
  { zh: "」相如曰：「夫以秦王之威而相如廷叱之，辱其群臣。", literal: "” Xiangru said, “Yet with the king of Qin's majesty, I publicly shouted him down in court and shamed his ministers.", idiomatic: "” Xiangru said, “Yet with the king of Qin's power I shouted him down in court and shamed his ministers." },
  { zh: "相如雖駑，獨畏廉將軍哉！", literal: "Though I am slow, would I alone fear General Lian!", idiomatic: "Slow as I am, would I fear General Lian alone?" },
  { zh: "顧吾念之，強秦〔之〕所以不敢加兵於趙者<ref>強秦〔之〕所以不敢加兵於趙者章校「十二行本『所』上有『之』字；", literal: "But when I consider it—the reason mighty Qin 〔之〕 dares not send troops against Zhao<ref>The reason mighty Qin 〔之〕 dares not send troops against Zhao—Zhang's collation: “In the twelve-line edition there is the character ‘之’ above ‘所’;", idiomatic: "But consider: the reason mighty Qin 〔之〕 dares not send troops against Zhao<ref>The reason mighty Qin 〔之〕 dares not send troops against Zhao—Zhang's collation: “In the twelve-line edition ‘之’ appears above ‘所’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong's edition agrees.", idiomatic: "Kong's edition agrees." },
  { zh: "」《史記·廉頗藺相如列傳》有，據補。", literal: "” Shiji “Biographies of Lian Po and Lin Xiangru” has it; supplemented accordingly.", idiomatic: "” Shiji “Biographies of Lian Po and Lin Xiangru” has it; supplemented accordingly." },
  { zh: "</ref>，徒以吾兩人在也。", literal: "</ref> is only because the two of us are here.", idiomatic: "</ref> is only because the two of us are here." },
  { zh: "今兩虎共斗，其勢不俱生。", literal: "Now if two tigers fight together, the outcome cannot be that both live.", idiomatic: "If two tigers fight, both cannot live." },
  { zh: "吾所以為此者，先國家之急而後私仇也。", literal: "The reason I act thus is to put the state's urgency first and private enmity after.", idiomatic: "I act thus because the state's need comes first and private grudges after." },
  { zh: "」廉頗聞之，肉袒負荊至門射罪，遂為刎頸之交。", literal: "” Lian Po heard this, bared his flesh and bore thorns to his door to declare guilt, and they became friends sworn unto death.", idiomatic: "” Lian Po heard, bared his breast and bore thorns to Xiangru's door to apologize, and they became sworn friends unto death." },
  { zh: "3初，燕人攻安平，臨淄市掾田單在安平，使其宗人皆以鐵籠傅車槥。", literal: "3 Earlier, when Yan men attacked Anping, Tian Dan, a market clerk of Linzi, was at Anping and had his clansmen all fit iron cages over their carriage shafts.", idiomatic: "3 Earlier, when Yan attacked Anping, Tian Dan, a market clerk of Linzi, was there and had his clansmen fit iron cages over their carriage shafts." },
  { zh: "及城潰，人爭門而出，皆以轊折車敗，為燕所禽；", literal: "When the city fell, men scrambled for the gates to flee; all broke their axles and ruined their carts, and were captured by Yan;", idiomatic: "When the city fell, men fought for the gates; axles snapped and carts broke, and Yan seized them;" },
  { zh: "獨田單宗人以鐵籠得免，遂奔即墨。", literal: "only Tian Dan's clansmen, thanks to the iron cages, escaped, and he fled to Jimo.", idiomatic: "only Tian Dan's clan, protected by the iron cages, escaped, and he fled to Jimo." },
  { zh: "是時齊地皆屬燕，獨莒、即墨未下，樂毅及並右軍、前軍以圍莒，左軍、後軍圍即墨。", literal: "At that time all Qi lands belonged to Yan; only Ju and Jimo had not fallen. Yue Yi, together with the merged right and van armies, besieged Ju; the left and rear armies besieged Jimo.", idiomatic: "By then all Qi belonged to Yan except Ju and Jimo. Yue Yi, with the united right and van armies, besieged Ju; the left and rear armies besieged Jimo." },
  { zh: "即墨大夫出戰而死。", literal: "The grandee of Jimo went out to battle and died.", idiomatic: "Jimo's commander went out to fight and was killed." },
  { zh: "即墨人曰：「安平之戰，田單宗人以鐵籠得全，是多智習兵。", literal: "The people of Jimo said, “At the battle of Anping, Tian Dan's clansmen were preserved by iron cages—he is very clever and skilled in arms.", idiomatic: "The people of Jimo said, “At Anping, Tian Dan's clan survived by iron cages—he is clever and knows war." },
  { zh: "」因共立以為將以拒燕。", literal: "” They therefore together installed him as general to resist Yan.", idiomatic: "” They together made him general to resist Yan." },
  { zh: "樂毅圍二邑，期年不克，及令解圍，各去城九里而為壘，令曰：「城中民出者勿獲，困者賑之，使即舊業，以鎮新民。", literal: "Yue Yi besieged the two cities a full year without taking them; eventually he ordered the siege lifted, each army withdrew nine li from the walls and built camps, and decreed, “Citizens who leave the cities—do not seize them; those in hardship—relieve them; let them resume their old occupations, to reassure the new people.", idiomatic: "Yue Yi besieged the two cities a year without success, then lifted the siege, drew nine li from each wall, and built camps. He decreed: “Let those who leave the cities go free; relieve the distressed; let them return to their trades, to calm the new subjects." },
  { zh: "」三年而猶未下。", literal: "” Three years passed and they still had not fallen.", idiomatic: "” Three years passed and they still had not fallen." },
  { zh: "或讒之於燕昭王曰：「樂毅智謀過人，伐齊，呼吸之間剋七十餘城。", literal: "Someone slandered him to King Zhao of Yan, saying, “Yue Yi's wisdom and schemes surpass other men; attacking Qi, in the space of a breath he took more than seventy cities.", idiomatic: "Someone slandered him to King Zhao of Yan: “Yue Yi's wit outdoes all men. Attacking Qi, he took more than seventy cities in a breath." },
  { zh: "今不下者兩城耳，非其力不能拔，所以三年不攻者，欲久仗兵威以服齊人，南面而王耳。", literal: "Now only two cities remain untaken—not that his strength cannot uproot them; the reason he has not attacked for three years is that he wishes long to wield military prestige to subdue the men of Qi and be king facing south.", idiomatic: "Only two cities remain—not that he cannot take them, but he has not attacked for three years because he means to hold his army's prestige until Qi submits, then be king facing south." },
  { zh: "今齊人已服，所以未發者，以其妻子在燕故也。", literal: "Now the men of Qi have submitted; the reason he has not declared himself is that his wife and children are in Yan.", idiomatic: "Qi is already won; he has not declared himself only because his wife and children are in Yan." },
  { zh: "且齊多美女，又將忘其妻子。", literal: "Moreover Qi has many beautiful women—he will again forget his wife and children.", idiomatic: "Moreover Qi has many fair women—he will forget wife and children again." },
  { zh: "願王圖之！", literal: "May Your Majesty take thought of this!", idiomatic: "May Your Majesty consider this!" },
  { zh: "」昭王於是置酒大會，引言者而讓之曰：「先王舉國以禮賢者，非貪土地以遺子孫也。", literal: "” King Zhao thereupon set out wine for a great assembly, brought forward the accuser and reproved him, saying, “The former king devoted the whole state to honor men of worth—not to covet territory to bequeath descendants.", idiomatic: "” King Zhao then held a great feast, brought forward the accuser, and rebuked him: “The former king devoted the whole state to honor the worthy—not to grab land for his heirs." },
  { zh: "遭所傳德薄，不能堪命，國人不順。", literal: "He met with thin virtue in what was handed down and could not bear the mandate; the people of the state were not compliant.", idiomatic: "The virtue he handed down was thin; he could not bear the charge, and the people would not obey." },
  { zh: "齊為無道，乘孤國之亂以害先王。", literal: "Qi was without the Way and seized upon our orphaned state's disorder to harm the former king.", idiomatic: "Qi was lawless and seized our orphaned state's disorder to harm the former king." },
  { zh: "寡人統位，痛之入骨，故廣延群臣，外招賓客，以求報仇。", literal: "When I inherited the throne the pain went to the marrow; therefore I widely gathered ministers and outwardly recruited guests, seeking revenge.", idiomatic: "When I took the throne the pain went to the bone; I gathered ministers far and wide and recruited guests from without, seeking revenge." },
  { zh: "其有成功者，尚欲與之同共燕國。", literal: "Whoever should succeed—I still intend to share Yan with him.", idiomatic: "Whoever succeeded, I meant still to share Yan with him." },
  { zh: "今樂君親為寡人破齊，夷其宗廟，報塞先仇，齊國固樂君所有，非燕之所得也。", literal: "Now Lord Yue has personally for me broken Qi, leveled its ancestral temples, and requited the former grievance—Qi in truth belongs to Lord Yue, not to what Yan can claim.", idiomatic: "Now Lord Yue has himself broken Qi for me, razed its temples, and settled the old score—Qi rightly belongs to Lord Yue, not to Yan." },
  { zh: "樂君若能有齊，與燕並為列國，結歡同好，以抗諸侯之難，燕國之福，寡人之願也。", literal: "If Lord Yue can hold Qi and stand with Yan as coequal states, joining friendship and good will to withstand the feudal lords' hardships—that is Yan's blessing and my wish.", idiomatic: "If Lord Yue can hold Qi and stand with Yan as equal states, joining in friendship to meet the lords' threats—that is Yan's blessing and my wish." },
  { zh: "汝何敢言若此！", literal: "How dare you speak thus!", idiomatic: "How dare you speak thus!" },
  { zh: "」乃斬之。", literal: "” He then beheaded him.", idiomatic: "” He then had him beheaded." },
  { zh: "賜樂毅妻以後服，賜其子以公子之服；", literal: "He bestowed on Yue Yi's wife the garb of a queen, on his son the garb of a young lord;", idiomatic: "He gave Yue Yi's wife a queen's robes and his son a young lord's dress;" },
  { zh: "輅車乘馬，後屬百兩，遣國相奉而致之樂毅，立樂毅為齊王。", literal: "a carriage and team, with a hundred coaches following behind; he sent the state chancellor to convey these to Yue Yi and install Yue Yi as king of Qi.", idiomatic: "a carriage and horses, a hundred coaches behind; he sent the chancellor to present them to Yue Yi and install him as king of Qi." },
  { zh: "樂毅惶恐不受，拜書，以死自誓。", literal: "Yue Yi in fear and awe did not accept, bowed in written reply, and pledged himself unto death.", idiomatic: "Yue Yi in fear refused, bowed in writing, and pledged his life." },
  { zh: "由是齊人服其義，諸侯畏其信，莫敢復有謀者。", literal: "From this the men of Qi submitted to his righteousness; the feudal lords feared his faith—none dared again plot against him.", idiomatic: "Then the men of Qi honored his integrity, the lords feared his loyalty, and none dared plot again." },
  { zh: "頃之，昭王薨，惠王立。", literal: "Before long King Zhao died and King Hui succeeded.", idiomatic: "Soon King Zhao died and King Hui succeeded." },
  { zh: "惠王自為太子時，嘗不快於樂毅。", literal: "King Hui, from the time he was crown prince, had once been displeased with Yue Yi.", idiomatic: "As crown prince, King Hui had once been displeased with Yue Yi." },
  { zh: "田單聞之，乃縱反間於燕，宣言曰：「齊王已死，城之不拔者二耳。", literal: "Tian Dan heard this and sent counter-intelligence into Yan, proclaiming, “The king of Qi is already dead; only two cities remain untaken.", idiomatic: "Tian Dan heard and sent disinformation into Yan, proclaiming: “The king of Qi is dead; only two cities still hold out." },
  { zh: "樂毅與燕新王有隙，畏誅而不敢歸，以伐齊為名，實欲連兵南面王齊。", literal: "Yue Yi has a rift with Yan's new king; fearing execution he dares not return. Under the name of attacking Qi he truly wishes to link armies and be king of Qi facing south.", idiomatic: "Yue Yi is at odds with Yan's new king; fearing death he dares not return. He attacks Qi in name only, but means to unite his forces and be king of Qi facing south." },
  { zh: "齊人未附，故且緩攻即墨以待其事。", literal: "The men of Qi are not yet attached; therefore he for now slows the attack on Jimo, awaiting the event.", idiomatic: "Qi is not yet won, so he delays the assault on Jimo, waiting for the moment." },
  { zh: "齊人所懼，唯恐他將之來，即墨殘矣。", literal: "What the men of Qi fear is only that another general will come—then Jimo will be destroyed.", idiomatic: "What Qi fears is only that another general will come—then Jimo will be ruined." },
  { zh: "」燕王固已疑樂毅，得齊反間，乃使騎劫代將而召樂毅。", literal: "” The king of Yan had already doubted Yue Yi; receiving Qi's counter-intelligence, he sent Qi Jie to replace him as general and summoned Yue Yi.", idiomatic: "” The king of Yan had already doubted Yue Yi; getting Qi's disinformation, he sent Qi Jie to replace him and summoned Yue Yi back." },
  { zh: "樂毅知王不善代之，遂奔趙。", literal: "Yue Yi knew the king's displeasure at replacing him and fled to Zhao.", idiomatic: "Yue Yi knew the king resented the replacement and fled to Zhao." },
  { zh: "燕將士由是憤惋不和。", literal: "Yan's generals and soldiers from this were angry, resentful, and discordant.", idiomatic: "Yan's officers and men from this were angry, aggrieved, and divided." },
  { zh: "田單令城中人，食必祭其先祖於庭，飛鳥皆翔舞而下城中。", literal: "Tian Dan ordered the people in the city, whenever they ate, to sacrifice to their ancestors in the courtyard; flying birds all soared and danced down into the city.", idiomatic: "Tian Dan ordered that whenever the people ate, they sacrifice to their ancestors in the courtyard; birds swooped and danced down into the city." },
  { zh: "燕人怪之，田單因宣言曰：「當有神師下教我。", literal: "The men of Yan found it strange; Tian Dan therefore proclaimed, “A divine teacher is about to descend and instruct me.", idiomatic: "The Yan troops marveled; Tian Dan proclaimed: “A divine teacher is about to descend and instruct me." },
  { zh: "」有一卒曰：「臣可以為師乎？", literal: "” A soldier said, “May your servant be that teacher?", idiomatic: "” A soldier said, “May I be that teacher?" },
  { zh: "」因反走。", literal: "” and turned and ran.", idiomatic: "” and ran off." },
  { zh: "田單起引還，坐東鄉，師事之。", literal: "Tian Dan rose, pulled him back, seated him facing east, and treated him as teacher.", idiomatic: "Tian Dan rose, brought him back, seated him facing east, and served him as teacher." },
  { zh: "卒曰：「臣欺君。", literal: "The soldier said, “Your servant deceived you.", idiomatic: "The soldier said, “I deceived you." },
  { zh: "」田單曰：「子勿言也。", literal: "” Tian Dan said, “Say no more.", idiomatic: "” Tian Dan said, “Say no more." },
  { zh: "」因師之，每出約束，必稱神師。", literal: "” He therefore kept him as teacher; whenever he issued orders he surely invoked the divine teacher.", idiomatic: "” He kept him as teacher; whenever he issued orders he invoked the divine teacher." },
  { zh: "乃宣言曰：「吾唯懼燕軍之劓所得齊卒，置之前行，即墨敗矣！", literal: "He then proclaimed, “I only fear that if Yan's army noses the Qi soldiers they have captured and places them in the van, Jimo will be lost!", idiomatic: "He then proclaimed: “I fear only that if Yan's army cuts the noses of captured Qi soldiers and puts them in the van, Jimo is lost!" },
  { zh: "」燕人聞之，如其言。", literal: "” The men of Yan heard it and acted as he had said.", idiomatic: "” The Yan troops heard it and did as he said." },
  { zh: "城中見降者盡劓，皆怒，堅守，唯恐見得。", literal: "In the city, seeing that surrendered men all had their noses cut, all were angry and held firm, fearing only being taken.", idiomatic: "In the city, seeing captured men with their noses cut off, all were enraged and held firm, fearing only capture." },
  { zh: "單又縱反間，言：「吾懼燕人掘吾城外塚墓，可為寒心！", literal: "Dan again sent counter-intelligence, saying, “I fear the men of Yan will dig up the graves outside our walls—how chilling to the heart!", idiomatic: "Tian Dan again sent disinformation, saying: “I fear Yan will dig up the graves outside our walls—how chilling!" },
  { zh: "」燕軍盡掘塚墓，燒死人。", literal: "” The Yan army dug up all the graves and burned the dead.", idiomatic: "” The Yan army dug up every grave and burned the corpses." },
  { zh: "齊人從城上望見，皆涕泣，共欲出戰，怒自十倍。", literal: "The men of Qi, looking down from the walls, all wept; together they wished to go out and fight, and their rage increased tenfold.", idiomatic: "The men of Qi on the walls saw it, wept, and together wanted to sally out; their rage redoubled ten times over." },
  { zh: "田單知士卒之可用，乃身操版、鍤，與士卒分功；", literal: "Tian Dan knew the soldiers could be used; he himself took mattock and spade and shared the work with the troops;", idiomatic: "Tian Dan knew his troops were ready; he himself took mattock and spade and shared their labor;" },
  { zh: "妻妾編於行伍之間；", literal: "his wife and concubines wove among the ranks;", idiomatic: "his wife and concubines wove among the ranks;" },
  { zh: "盡散飲食饗士。", literal: "he gave out all food and drink to feast the soldiers.", idiomatic: "he gave out all food and drink to feast his men." },
  { zh: "令甲卒皆伏，使老、弱、女子乘城，遣使約降於燕，燕軍皆呼萬歲。", literal: "He ordered armored soldiers all to lie hidden, had the old, weak, and women man the walls, sent envoys to treat for surrender with Yan, and the Yan army all shouted “Long live!", idiomatic: "He hid the armored troops, put the old, weak, and women on the walls, sent envoys to negotiate surrender with Yan, and the Yan army shouted “Long live!" },
  { zh: "田單又收民金得千鎰，令即墨富豪遺燕將，曰：「即降，願無虜掠吾族家。", literal: "Tian Dan also collected from the people a thousand yi in gold and had the wealthy of Jimo present it to the Yan general, saying, “When we surrender, we beg that our clans and homes not be plundered.", idiomatic: "Tian Dan also collected a thousand yi of gold from the people and had Jimo's wealthy present it to the Yan general, saying: “When we surrender, do not plunder our families and homes." },
  { zh: "」燕將大喜，許之。", literal: "” The Yan general was greatly pleased and promised.", idiomatic: "” The Yan general was delighted and agreed." },
  { zh: "燕軍益懈。", literal: "The Yan army grew still more slack.", idiomatic: "The Yan army grew still more slack." },
  { zh: "田單乃收城中，得牛千餘，為絳繒衣，畫以五采龍文，束兵刃於其角，而灌脂束葦於其尾，燒其端，鑿城數十穴，夜縱牛，壯士五千〔人〕隨其後<ref>壯士五千〔人〕隨其後據《史記·田單列傳》補。", literal: "Tian Dan then gathered in the city more than a thousand oxen, made crimson silk coats for them, painted them with five-colored dragon designs, bound blades to their horns, poured grease and bound reeds to their tails, burned the tips, bored several dozen holes in the wall, and by night released the oxen, with five thousand 〔men〕 of stout warriors following behind<ref>with five thousand 〔men〕 of stout warriors following behind—supplemented per Shiji “Biography of Tian Dan”.", idiomatic: "Tian Dan then gathered more than a thousand oxen in the city, fitted them with crimson silk coats painted with five-colored dragons, bound blades to their horns, greased and bound reeds to their tails, set the tips afire, bored several dozen holes in the wall, and by night released the oxen, with five thousand 〔men〕 of stout warriors behind<ref>“five thousand 〔men〕 of stout warriors behind”—added from Shiji “Biography of Tian Dan”." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "牛尾熱，怒而奔燕軍。", literal: "The oxen's tails burned hot; enraged, they charged the Yan army.", idiomatic: "Their tails burned hot; enraged, the oxen charged the Yan army." },
  { zh: "燕軍大驚，視牛皆龍文，所觸盡死傷。", literal: "The Yan army was greatly alarmed; seeing the oxen all bore dragon designs, whatever they touched was killed or wounded.", idiomatic: "The Yan army panicked; the oxen seemed all dragon-marked, and whatever they struck was killed or wounded." },
  { zh: "而城中鼓噪從之，老弱皆擊銅器為聲，聲動天地。", literal: "Meanwhile in the city drums and shouts followed them; old and weak all struck bronze vessels for sound—the noise shook heaven and earth.", idiomatic: "Meanwhile the city drummed and shouted in pursuit; young and old beat bronze vessels until the noise shook heaven and earth." },
  { zh: "燕軍大駭，敗走。", literal: "The Yan army was greatly terrified and fled in defeat.", idiomatic: "The Yan army was terrified and fled in rout." },
  { zh: "齊人殺騎劫，追亡逐北，所過城邑皆叛燕，復為齊。", literal: "The men of Qi killed Qi Jie, pursued the fleeing and routed the northward; every city they passed rebelled against Yan and returned to Qi.", idiomatic: "The men of Qi killed Qi Jie and pursued the fugitives; every city they passed rebelled against Yan and returned to Qi." },
  { zh: "田單兵日益多，乘勝，燕日敗亡，走至河上，而齊七十餘城皆復焉。", literal: "Tian Dan's troops daily grew more numerous; riding victory, Yan daily was defeated and destroyed, fleeing to the river—and more than seventy cities of Qi were all restored.", idiomatic: "Tian Dan's army grew daily; pressing the victory, Yan fell back day by day to the river, and more than seventy cities of Qi were restored." },
  { zh: "乃迎襄王於莒。", literal: "He thereupon welcomed King Xiang from Ju.", idiomatic: "He then welcomed King Xiang from Ju." },
  { zh: "入臨淄，封田單為安平君。", literal: "Entering Linzi, he enfeoffed Tian Dan as Lord of Anping.", idiomatic: "Entering Linzi, he enfeoffed Tian Dan as Lord of Anping." },
  { zh: "齊王以太史敫之女為後，生太子建。", literal: "The king of Qi took the daughter of Grand Clerk Ji as consort; she bore the crown prince Jian.", idiomatic: "The king of Qi took Grand Clerk Ji's daughter as consort; she bore Crown Prince Jian." },
  { zh: "太史敫曰：「女不取媒，因自嫁，非吾種也，汙吾世！", literal: "Grand Clerk Ji said, “My daughter took no go-between and married of herself—she is not of my kind; she stains my house!", idiomatic: "Grand Clerk Ji said: “My daughter took no matchmaker and married on her own—she is not of my blood; she stains my line!" },
  { zh: "」終身不見君王后，君王后亦不以不見故失人子之禮。", literal: "” He never in his life saw the queen; the queen also, on account of not being seen, did not fail in the rites due a parent from a child.", idiomatic: "” He never saw the queen in his life; the queen also, though never received, did not fail in a daughter's duty toward him." },
  { zh: "趙王封樂毅於觀津，尊寵之，以警動於燕、齊。", literal: "The king of Zhao enfeoffed Yue Yi at Guanjin, honored and favored him, to alarm and stir Yan and Qi.", idiomatic: "The king of Zhao enfeoffed Yue Yi at Guanjin and honored him lavishly, to warn and stir Yan and Qi." },
  { zh: "燕惠王乃使人讓樂毅，且謝之曰：「將軍過聽，以與寡人有隙，遂捐燕歸趙。", literal: "King Hui of Yan thereupon sent someone to reproach Yue Yi and also apologize, saying, “The general listened too far and, having a rift with me, abandoned Yan and returned to Zhao.", idiomatic: "King Hui of Yan sent someone to reproach Yue Yi and also to apologize: “General, you listened too readily, took offense at me, abandoned Yan, and went to Zhao." },
  { zh: "將軍自為計則可矣，而亦何以報先王這所以遇將軍之意乎？", literal: "The general may plan for himself—but how will you repay what the former king meant by how he treated the general?", idiomatic: "You may look to your own interest—but how will you repay what the former king meant by how he honored you?" },
  { zh: "」樂毅報書曰：「昔伍子胥說聽於闔閭而吳遠跡至郢；", literal: "” Yue Yi replied in writing, saying, “Of old Wu Zixu spoke and was heeded by Helü, and Wu's tracks reached far to Ying;", idiomatic: "” Yue Yi wrote back: “Of old Wu Zixu was heeded by King Helü of Wu, and Wu's armies reached as far as Ying;" },
  { zh: "夫差弗是也，賜之鴟夷而浮之江。", literal: "Fuchai did not approve and bestowed on him the owl-skin bag and floated him on the river.", idiomatic: "Fuchai would not have it, gave him the leather sack, and set him adrift on the river." },
  { zh: "吳王不寤先論之可以立功，故沈子胥而不悔；", literal: "The king of Wu did not awaken to how the former counsel could establish merit; therefore he drowned Zixu and did not repent;", idiomatic: "The king of Wu did not see that the earlier counsel could win merit, so he drowned Zixu unrepentant;" },
  { zh: "子胥不蚤見主之不同量，是以至於入江而不化。", literal: "Zixu did not early perceive that his lord's measure differed—thus he came to entering the river and did not transform.", idiomatic: "Zixu did not early see that his lord's measure differed—thus he entered the river and was lost." },
  { zh: "夫免自立功以明先王之跡，臣之上計也。", literal: "To escape, establish merit, and clarify the former king's achievement—that is your servant's upper plan.", idiomatic: "To escape, win merit, and vindicate the former king's design—that is my best course." },
  { zh: "離毀辱之誹謗，墮先王之名，臣之所大恐也。", literal: "To leave slander of ruin and insult and bring down the former king's name—that is what your servant greatly fears.", idiomatic: "To flee slander and disgrace and stain the former king's name—that is what I most fear." },
  { zh: "臨不測之罪，以幸為利，義之所不敢出也。", literal: "Facing unpredictable guilt and taking luck for profit—righteousness dares not offer this.", idiomatic: "To face uncertain punishment and take advantage for profit—right conduct forbids it." },
  { zh: "臣聞古之君子，交絕不出惡聲，忠臣去國，不潔其名。", literal: "Your servant has heard that ancient gentlemen, when breaking off relations, utter no evil sound; loyal ministers who leave a state do not stain their names.", idiomatic: "I have heard that gentlemen of old, when breaking with someone, spoke no evil; loyal ministers who left a state did not stain their names." },
  { zh: "臣雖不佞，數奉教於君子矣。", literal: "Though your servant is not talented, I have several times received instruction from gentlemen.", idiomatic: "Though I am not worthy, I have often been taught by gentlemen." },
  { zh: "唯君王之留意焉！", literal: "May Your Majesty only take thought of this!", idiomatic: "May Your Majesty only bear this in mind!" },
  { zh: "」於是燕王復以樂毅子閒為昌國君，而樂毅往來復通燕，卒於趙，號曰望諸君。", literal: "” Thereupon the king of Yan again made Yue Yi's son Xian lord of Chang, while Yue Yi went back and forth and again had dealings with Yan; he died in Zhao and was styled Lord Wangzhu.", idiomatic: "” Thereupon the king of Yan again made Yue Yi's son Xian lord of Chang; Yue Yi resumed contact with Yan; he died in Zhao and was styled Lord Wangzhu." },
  { zh: "田單相齊，過淄水，有老人涉淄而寒，出水不能行。", literal: "Tian Dan, as chancellor of Qi, crossed the Zi River; an old man forded the Zi and was cold—coming out of the water he could not walk.", idiomatic: "As chancellor of Qi, Tian Dan was crossing the Zi when an old man waded the river, took cold, and could not walk after coming out." },
  { zh: "田單解其裘而衣之。", literal: "Tian Dan removed his fur coat and clothed him in it.", idiomatic: "Tian Dan took off his fur coat and put it on him." },
  { zh: "襄王惡之，曰：「田單之施於人，將〔欲〕以取我國乎<ref>將〔欲〕以取我國乎據《史記·田單列傳》補。", literal: "King Xiang resented it and said, “Tian Dan's kindness to others—is he 〔wishing〕 to seize my state?<ref>is he 〔wishing〕 to seize my state?—supplemented per Shiji “Biography of Tian Dan”.", idiomatic: "King Xiang took offense and said: “Tian Dan's kindness to others—is he 〔trying〕 to take my state?<ref>“〔trying〕 to take my state”—added from Shiji “Biography of Tian Dan”." },
  { zh: "</ref>？", literal: "</ref>?", idiomatic: "</ref>?" },
  { zh: "不早圖，恐後之變也。", literal: "If we do not plan early, I fear trouble later.", idiomatic: "If we do not act early, I fear trouble later." },
  { zh: "」左右顧無人，巖下有貫珠者，襄王呼而問之曰：「汝聞吾言乎？", literal: "” He looked to left and right—no one was there; below the cliff was one who strung pearls. King Xiang called and asked him, saying, “Did you hear my words?", idiomatic: "” He looked about—no one was near; below the cliff a pearl-stringer sat. King Xiang called him and asked: “Did you hear what I said?" },
  { zh: "」對曰：「聞之。", literal: "” He answered, “I heard.", idiomatic: "” He answered: “I heard." },
  { zh: "」王曰：「汝以為何如？", literal: "” The king said, “What do you think of it?", idiomatic: "” The king said: “What do you think?" },
  { zh: "」對曰：「王不如因以為己善。", literal: "” He answered, “Your Majesty would do better to turn it to your own credit.", idiomatic: "” He answered: “Your Majesty should turn it to your own credit." },
  { zh: "王嘉單之善，下令曰：『寡人憂民之飢也，單收而食之；", literal: "Your Majesty should praise Dan's goodness and issue an order, saying, ‘I worry that the people hunger—Dan gathers them and feeds them;", idiomatic: "Praise Tian Dan's goodness and decree: ‘I worry that the people hunger—Tian Dan gathers them and feeds them;" },
  { zh: "寡人憂民之寒也，單解裘而衣之；", literal: "I worry that the people are cold—Dan removes his fur coat and clothes them;", idiomatic: "I worry that the people are cold—Tian Dan strips off his fur coat and clothes them;" },
  { zh: "寡人憂勞百姓，而單亦憂〔之〕<ref>而單亦憂〔之〕據《史記·田單列傳》補。", literal: "I worry over toiling the hundred surnames, and Dan also worries 〔over it〕<ref>and Dan also worries 〔over it〕—supplemented per Shiji “Biography of Tian Dan”.", idiomatic: "I worry over the people's burdens, and Tian Dan worries 〔over them〕 too<ref>“worries 〔over them〕 too”—added from Shiji “Biography of Tian Dan”." },
  { zh: "</ref>，稱寡人之意。", literal: "</ref>, echoing my intent.", idiomatic: "</ref>, echoing my intent." },
  { zh: "』單有是善而王嘉之，單之善亦王之善也。", literal: "’ When Dan has such goodness and Your Majesty praises it, Dan's goodness is also Your Majesty's goodness.", idiomatic: "’ When Tian Dan does good and Your Majesty praises it, his goodness is Your Majesty's goodness." },
  { zh: "」王曰：「善。", literal: "” The king said, “Good.", idiomatic: "” The king said: “Well said." },
  { zh: "」乃賜單牛酒。", literal: "” He then bestowed on Dan oxen and wine.", idiomatic: "” He then gave Tian Dan oxen and wine." },
  { zh: "後數日，貫珠者復見王曰：「王朝日宜召田單而揖之於庭，口勞之。", literal: "Several days later the pearl-stringer again saw the king and said, “Your Majesty should daily summon Tian Dan, bow to him in the court, and comfort him with words.", idiomatic: "Days later the pearl-stringer saw the king again and said: “Your Majesty should summon Tian Dan each morning, bow to him in court, and speak words of comfort." },
  { zh: "乃布令求百姓之饑寒者，收穀之。", literal: "Then issue a public order seeking among the hundred surnames those who hunger or are cold, and gather grain for them.", idiomatic: "Then proclaim that you seek the hungry and cold among the people and will gather grain for them." },
  { zh: "」乃使人聽於閭里，聞大夫之相與語者曰：「田單之愛人，嗟，乃王之教也！", literal: "” He then had men listen in the lanes and alleys; they heard grandees speaking together, saying, “Tian Dan's love for the people—ah, it is the king's teaching!", idiomatic: "” He had men listen in the lanes; they heard officials saying: “Tian Dan's care for the people—ah, that is the king's teaching!" },
  { zh: "田單任貂勃於王。", literal: "Tian Dan entrusted Diao Bo to the king.", idiomatic: "Tian Dan recommended Diao Bo to the king." },
  { zh: "王有所幸臣九人，欲傷安平君，相與語於王曰：「燕之伐齊之時，楚王使將軍將萬人而佐齊。", literal: "The king had nine favored ministers who wished to harm the Lord of Anping; they spoke together to the king, saying, “When Yan attacked Qi, the king of Chu sent a general with ten thousand men to assist Qi.", idiomatic: "The king had nine favored ministers who wished to harm Lord Anping; they said to the king: “When Yan attacked Qi, the king of Chu sent a general with ten thousand men to aid Qi." },
  { zh: "今國已定而社稷已安矣，何不使使者謝於楚王？", literal: "Now the state is settled and the altars are secure—why not send an envoy to thank the king of Chu?", idiomatic: "Now the state is settled and the altars secure—why not send an envoy to thank the king of Chu?" },
  { zh: "」王曰：「左右孰可？", literal: "” The king said, “Who among those at hand will do?", idiomatic: "” The king said: “Who among my attendants will do?" },
  { zh: "」九人之屬曰：「貂勃可。", literal: "” The nine men's faction said, “Diao Bo will do.", idiomatic: "” The nine said: “Diao Bo will do." },
  { zh: "」貂勃使楚，楚王受而觴之，數月不反。", literal: "” Diao Bo was sent to Chu; the king of Chu received and feasted him, and for several months he did not return.", idiomatic: "” Diao Bo went to Chu; the king of Chu received and feasted him, and for months he did not return." },
  { zh: "九人之屬相與語〔於王〕曰<ref>九人之屬相與語〔於王〕曰據《史記·田單列傳》補。", literal: "The nine men's faction spoke together 〔to the king〕, saying<ref>spoke together 〔to the king〕, saying—supplemented per Shiji “Biography of Tian Dan”.", idiomatic: "The nine spoke together 〔to the king〕, saying<ref>“spoke together 〔to the king〕”—added from Shiji “Biography of Tian Dan”." },
  { zh: "</ref>：「夫一人之身而牽留萬乘者，豈不以據勢也哉！", literal: "</ref>: “That one man's person should detain a state of ten thousand chariots—is it not because he holds power!", idiomatic: "</ref>: “That one man should hold back a state of ten thousand chariots—is it not because he holds power!" },
  { zh: "且安平君之與王也，君臣無異而上下無別。", literal: "Moreover, between the Lord of Anping and Your Majesty there is no difference between minister and lord, nor distinction between above and below.", idiomatic: "Moreover, between Lord Anping and Your Majesty there is no difference of minister and lord, nor of high and low." },
  { zh: "且其志欲為不善，內撫百姓，外懷戎翟，禮天下之賢士，其志欲有為〔也〕，願王察之<ref>其志欲有為〔也〕願王察之章校「十二行本『為』下有『也』字，『王』下有『之』字；", literal: "Moreover his intent wishes ill; inwardly he comforts the hundred surnames, outwardly he embraces the Rong and Di, treats with rites the worthy men under Heaven—his intent wishes to act 〔也〕; may Your Majesty examine this<ref>his intent wishes to act 〔也〕; may Your Majesty examine this—Zhang's collation: “In the twelve-line edition below ‘act’ is the character ‘也’, and below ‘Majesty’ is the character ‘之’;", idiomatic: "Moreover he means ill: inwardly he wins the people, outwardly he courts the Rong and Di, honors the worthy under Heaven—he means to act 〔也〕; may Your Majesty look into it<ref>“means to act 〔也〕; may Your Majesty look into it”—Zhang's collation: “In the twelve-line edition ‘也’ follows ‘為’, and ‘之’ follows ‘王’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "退齋校云：『為』下有『也』字。", literal: "Tui Zhai's collation says: below ‘act’ is the character ‘也’.", idiomatic: "Tui Zhai's collation says: ‘也’ follows ‘為’." },
  { zh: "」今據補「也」，「之」字不補亦通。", literal: "” Now ‘也’ is supplemented accordingly; not supplementing ‘之’ is also intelligible.", idiomatic: "” ‘也’ is supplemented accordingly; omitting ‘之’ is also intelligible." },
  { zh: "</ref>！", literal: "</ref>!", idiomatic: "</ref>!" },
  { zh: "」異日，王曰：「召相單而來！", literal: "” Another day the king said, “Summon Chancellor Dan to come!", idiomatic: "” Another day the king said: “Summon Chancellor Tian Dan!" },
  { zh: "」田單免冠、徒跣、肉袒而進，退而請死罪，五日而王曰：「子無罪於寡人。", literal: "” Tian Dan removed cap and shoes, bared his flesh, and advanced; withdrawing he begged the death penalty. Five days later the king said, “You have no guilt toward me.", idiomatic: "” Tian Dan came bareheaded, barefoot, and bare-chested; withdrawing he asked for death. Five days later the king said: “You have done me no wrong." },
  { zh: "子為子之臣禮，吾為吾之王禮而已矣。", literal: "You perform your rites as minister; I perform my rites as king—that is all.", idiomatic: "You keep your rites as minister; I keep mine as king—that is all." },
  { zh: "」貂勃從楚來，王賜之酒。", literal: "” Diao Bo returned from Chu; the king gave him wine.", idiomatic: "” Diao Bo returned from Chu, and the king gave him wine." },
  { zh: "酒酣，王曰：「召相單而來！", literal: "When the wine was warm, the king said, “Summon Chancellor Dan to come!", idiomatic: "When the wine was warm, the king said: “Summon Chancellor Tian Dan!" },
  { zh: "」貂勃避席稽首曰：「王上者孰與周文王？", literal: "” Diao Bo left his mat, bowed head to ground, and said, “Your Majesty above—how do you compare with King Wen of Zhou?", idiomatic: "” Diao Bo left his mat, kowtowed, and said: “Your Majesty above—how do you compare with King Wen of Zhou?" },
  { zh: "」王曰：「吾不若也。", literal: "” The king said, “I do not equal him.", idiomatic: "” The king said: “I do not." },
  { zh: "」貂勃曰：「然，臣固知王不若也。", literal: "” Diao Bo said, “So; your servant always knew Your Majesty did not equal him.", idiomatic: "” Diao Bo said: “So; I always knew Your Majesty did not." },
  { zh: "下者孰與齊桓公？", literal: "Below—how do you compare with Duke Huan of Qi?", idiomatic: "Below—how do you compare with Duke Huan of Qi?" },
  { zh: "」王曰：「吾不若也。", literal: "” The king said, “I do not equal him.", idiomatic: "” The king said: “I do not." },
  { zh: "」貂勃曰：「然，臣固知王不若也。", literal: "” Diao Bo said, “So; your servant always knew Your Majesty did not equal him.", idiomatic: "” Diao Bo said: “So; I always knew Your Majesty did not." },
  { zh: "然則周文王得呂尚以為太公，齊桓公得管夷吾以為仲父，今王得安平君而獨曰『單』，安得此亡國之言乎！", literal: "Yet King Wen of Zhou got Lü Shang and made him Grand Duke; Duke Huan of Qi got Guan Yiwu and made him Uncle-Father; now Your Majesty has the Lord of Anping yet alone say ‘Dan’—how can there be such talk of a state's ruin!", idiomatic: "Yet King Wen made Lü Shang his Grand Duke, Duke Huan made Guan Yiwu his Uncle-Father—yet Your Majesty has Lord Anping and calls him only ‘Dan’! How can there be such talk of ruin!" },
  { zh: "且自天地之辟，民人之始，為人臣之功者，誰有厚於安平君者哉？", literal: "Moreover, from the opening of Heaven and Earth and the beginning of the people, among the achievements of men who served as ministers—who has been thicker than the Lord of Anping?", idiomatic: "Moreover, since Heaven and Earth began and men arose, who among ministers has done more than Lord Anping?" },
  { zh: "王不能守王之社稷，燕人興師而襲齊，王走而之城陽之山中，安平君以惴惴即墨三里之城，五里之郭，敝卒七千人，禽其司馬而反千里之齊，安平君之功也。", literal: "Your Majesty could not keep your altars; the men of Yan raised troops and struck Qi; Your Majesty fled to the mountains at Chengyang. The Lord of Anping, in fear and trembling, with Jimo's three-li walls and five-li outer works and seven thousand worn troops, captured their marshal and restored a thousand li of Qi—that is the Lord of Anping's achievement.", idiomatic: "Your Majesty could not hold the altars; Yan raised troops and struck Qi; you fled to the mountains at Chengyang. Lord Anping, in fear and trembling, with Jimo's three-li walls, five-li suburbs, and seven thousand worn troops, captured their marshal and restored a thousand li of Qi—that is Lord Anping's merit." },
  { zh: "當是之時，舍城陽而自王，天下莫之能止。", literal: "At that time, had he abandoned Chengyang and made himself king, none under Heaven could have stopped him.", idiomatic: "At that time, had he left Chengyang and made himself king, none under Heaven could have stopped him." },
  { zh: "然而計之於道，歸之於義，以為不可，故棧道木閣而迎王與后於城陽山中，王乃得反，子臨百姓。", literal: "Yet he reckoned by the Way and returned to righteousness, deemed it impossible, and therefore built plank roads and wooden galleries to welcome Your Majesty and the queen from the mountains at Chengyang; only then did Your Majesty return and rule the hundred surnames.", idiomatic: "Yet he reckoned by the Way and by righteousness, held it wrong, built plank roads and wooden galleries to welcome you and the queen from the Chengyang hills, and only then did you return to rule the people." },
  { zh: "今國已定，民已安矣，王乃曰『單』，嬰兒之計不為此也。", literal: "Now the state is settled and the people are secure—yet Your Majesty says ‘Dan’; no child's plan would do this.", idiomatic: "Now the state is settled and the people secure—yet Your Majesty says only ‘Dan’; not even a child's plan would do this." },
  { zh: "王亟殺此九子者以謝安平君，不然，國其危矣！", literal: "Your Majesty should quickly kill these nine men to apologize to the Lord of Anping—otherwise the state will be in peril!", idiomatic: "Your Majesty should quickly kill these nine and apologize to Lord Anping—or the state is in peril!" },
  { zh: "」乃殺九子而逐其家，益封安平君以夜邑萬戶<ref>益封安平君以夜邑萬戶「夜邑」，《戰國策》作「掖邑」，班固《漢書》有掖縣，蓋是此地。", literal: "” He then killed the nine men and banished their households, and increased the Lord of Anping's fief by the ten-thousand-household district of Ye<ref>increased the Lord of Anping's fief by the ten-thousand-household district of Ye—“Ye district” in Strategies of the Warring States reads “Ye district” as 掖邑; Ban Gu's Book of Han has Ye county—probably this place.", idiomatic: "” He killed the nine and banished their families, and added to Lord Anping's fief the ten-thousand-household district of Ye<ref>“Ye district” (夜邑)—Strategies of the Warring States has 掖邑; Ban Gu's Book of Han has Ye county—probably this place." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "田單將攻狄，往見魯仲連。", literal: "Tian Dan was about to attack Di and went to see Lu Zhonglian.", idiomatic: "Tian Dan was about to attack Di and went to see Lu Zhonglian." },
  { zh: "魯仲連曰：「將軍攻狄，不能下也。", literal: "Lu Zhonglian said, “General, if you attack Di you will not take it.", idiomatic: "Lu Zhonglian said: “General, you will not take Di." },
  { zh: "」田單曰：「臣以即墨破亡餘卒破萬乘之燕，復齊之墟，今攻狄而不下，何也？", literal: "” Tian Dan said, “Your servant, with Jimo's broken remnant troops, broke ten-thousand-chariot Yan and restored Qi's ruins—now attacking Di and not taking it: why?", idiomatic: "” Tian Dan said: “With Jimo's broken remnant I broke ten-thousand-chariot Yan and restored Qi's lands—why can I not take Di now?" },
  { zh: "」上車弗謝而去，遂攻狄，三月不克。", literal: "” He mounted his carriage without thanking him and left; he then attacked Di, and for three months could not take it.", idiomatic: "” He mounted his carriage without a word of thanks and left; he attacked Di three months without success." },
  { zh: "齊小兒謠曰：「大冠若箕，修劍拄頤。", literal: "The children of Qi sang a rhyme: “Great cap like a winnowing-basket, long sword propping the chin.", idiomatic: "The children of Qi sang: “Cap big as a basket, long sword propping his chin." },
  { zh: "攻狄不能下，壘枯骨成丘。", literal: "Attacking Di and not taking it—he piles dry bones into hills.", idiomatic: "Cannot take Di—he piles dry bones into hills." },
  { zh: "」田單乃懼，問魯仲連曰：「先生謂單不能下狄，請問其說。", literal: "” Tian Dan then grew afraid and asked Lu Zhonglian, “The master said Dan could not take Di—may I ask the reason?", idiomatic: "” Tian Dan grew afraid and asked Lu Zhonglian: “You said I could not take Di—may I ask why?" },
  { zh: "」魯仲連曰：「將軍之在即墨，坐則織蕢，立則仗鍤，為士卒倡曰：『無可往矣！", literal: "” Lu Zhonglian said, “When the general was at Jimo, sitting he wove reed mats, standing he leaned on a spade, and for the soldiers led the chant, saying, ‘There is nowhere to go!", idiomatic: "” Lu Zhonglian said, “At Jimo you sat weaving reed mats and stood leaning on a spade, leading the soldiers in a chant: ‘There is nowhere left to go!" },
  { zh: "宗廟亡矣！", literal: "The ancestral temples are lost!", idiomatic: "The ancestral temples are lost!" },
  { zh: "今日尚矣！", literal: "Today is the last!", idiomatic: "Today is the end!" },
  { zh: "歸於何黨矣！", literal: "To which clan shall we return!", idiomatic: "To which clan can we return!" },
  { zh: "』當此之時，將軍有死之心，士卒先無之氣，聞君言莫不揮泣奮臂而欲戰，此所以破燕也。", literal: "’ At that time the general had the will to die; the soldiers beforehand lacked such spirit; hearing your words none failed to weep, wave their arms, and wish to fight—this is why Yan was broken.", idiomatic: "’ Then you were ready to die and your men had lost heart; at your words every man wept, raised his arms, and burned to fight—that is how Yan was broken." },
  { zh: "當今將軍東有夜邑之奉，西有淄上之娛，黃金橫帶而騁乎淄、澠之間，有生之樂，無死之心，所以不勝也。", literal: "Now the general has Ye city's revenue in the east and amusements on the Zi in the west, gold across his belt galloping between the Zi and the Mian, the pleasures of life and no will to die—this is why he cannot win.", idiomatic: "Now you have Ye's revenues in the east and pleasures on the Zi in the west, gold at your belt, galloping between the Zi and the Mian—the joy of living and no will to die. That is why you cannot win." },
  { zh: "」田單曰：「單之有心，先生志之矣。", literal: "” Tian Dan said, “Dan's heart—the master has recorded it.", idiomatic: "” Tian Dan said, “You have read my heart, sir." },
  { zh: "」明日，乃厲氣循城，立於矢石之所，援袍鼓之。", literal: "” The next day he stiffened his resolve and went round the wall, stood where arrows and stones fell, took cloak and drumstick and beat the drum.", idiomatic: "” Next day he roused his spirit, circled the wall, stood where arrows and stones fell, and beat the war drum." },
  { zh: "狄人乃下。", literal: "The Di then came down.", idiomatic: "The Di then surrendered." },
  { zh: "初，齊湣王既滅宋，欲去孟嘗君。", literal: "Earlier, after King Min of Qi had destroyed Song, he wished to remove Lord Mengchang.", idiomatic: "Earlier, after King Min of Qi destroyed Song, he wished to remove Lord Mengchang." },
  { zh: "孟嘗君奔魏，魏昭王以為相，與諸侯共伐破齊。", literal: "Lord Mengchang fled to Wei; King Zhao of Wei made him chancellor, and with the feudal lords together attacked and broke Qi.", idiomatic: "Lord Mengchang fled to Wei. King Zhao of Wei made him chancellor, and with the other lords he helped smash Qi." },
  { zh: "湣王死，襄王復國，而孟嘗君中立為諸侯，無所屬。", literal: "King Min died; King Xiang restored the state, while Lord Mengchang stood neutral as a feudal lord, belonging to none.", idiomatic: "King Min died. King Xiang restored Qi, while Lord Mengchang held himself neutral among the lords, belonging to no one." },
  { zh: "襄王新立，畏孟嘗君，與之連和。", literal: "King Xiang had newly succeeded and feared Lord Mengchang; he joined in alliance with him.", idiomatic: "The newly enthroned King Xiang feared Lord Mengchang and allied with him." },
  { zh: "孟嘗君卒，諸子爭立，而齊、魏共滅薛，孟嘗君絕嗣。", literal: "Lord Mengchang died; his sons contended for succession, and Qi and Wei together destroyed Xue—Lord Mengchang's line ended.", idiomatic: "Lord Mengchang died. His sons fought over the succession; Qi and Wei together destroyed Xue, and his line died out." },
  { zh: "2〔魯緡公薨，子頃公讎立〕<ref>〔魯緡公薨子頃公讎立〕舊文本繫於赧王四十一年，據近人考証移入此年。", literal: "2 〔Duke Min of Lu died; his son Duke Qing Chou succeeded〕<ref>〔Duke Min of Lu died; Duke Qing Chou succeeded〕The old text placed this under King Nan's forty-first year; moved to this year per modern scholarship.", idiomatic: "2 〔Duke Min of Lu died; his son Duke Qing Chou succeeded〕<ref>〔Duke Min of Lu died; Duke Qing Chou succeeded〕The old text placed this under King Nan's forty-first year; moved to this year per modern scholarship." },
  { zh: "並據赧王四十八年條改「湣」為「緡」。", literal: "Also, per the entry for King Nan's forty-eighth year, emended ‘Min’ to ‘Min (緡).’", idiomatic: "Also, per the entry for King Nan's forty-eighth year, emended ‘Min’ to ‘Min (緡).’" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1秦大良造白起伐楚，拔郢，燒夷陵。", literal: "1 Qin's Grand Provisioner Bai Qi attacked Chu, took Ying, and burned Yiling.", idiomatic: "1 Qin's Grand Provisioner Bai Qi attacked Chu, took Ying, and burned Yiling." },
  { zh: "楚襄王兵散，遂不復戰，東北徙都於陳。", literal: "King Xiang of Chu's army scattered; he then fought no more and moved the capital northeast to Chen.", idiomatic: "King Xiang of Chu's army scattered. He fought no more and moved the capital northeast to Chen." },
  { zh: "秦以郢為南郡，封白起為武安君。", literal: "Qin made Ying the southern commandery and enfeoffed Bai Qi as Lord Wu'an.", idiomatic: "Qin made Ying the southern commandery and enfeoffed Bai Qi as Lord Wu'an." },
  { zh: "1秦武安君定巫、黔中，初置黔中郡。", literal: "1 Lord Wu'an of Qin settled Wu and Qianzhong and for the first time established the commandery of Qianzhong.", idiomatic: "1 Lord Wu'an of Qin settled Wu and Qianzhong and for the first time established the commandery of Qianzhong." },
  { zh: "2魏昭王薨，子安釐王〔圉〕立<ref>子安釐王〔圉〕立據《史記·魏世家》索隱引《世本》補。", literal: "2 King Zhao of Wei died; his son King Anxi 〔Yuan〕 succeeded<ref>King Anxi 〔Yuan〕 succeeded—supplemented per Suoyin on Shiji “House of Wei,” citing Shiben.", idiomatic: "2 King Zhao of Wei died; his son King Anxi 〔Yuan〕 succeeded<ref>King Anxi 〔Yuan〕 succeeded—supplemented per Suoyin on Shiji “House of Wei,” citing Shiben." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1秦武安君伐魏，拔兩城。", literal: "1 Lord Wu'an of Qin attacked Wei and took two cities.", idiomatic: "1 Lord Wu'an of Qin attacked Wei and took two cities." },
  { zh: "2楚王收東地兵，得十餘萬，復西取江南十五邑。", literal: "2 The king of Chu gathered troops from the eastern lands, obtained more than a hundred thousand, and again westward took fifteen districts of Jiangnan.", idiomatic: "2 The king of Chu gathered eastern troops, raised more than a hundred thousand men, and again took fifteen districts in Jiangnan." },
  { zh: "3魏安釐王封其弟無忌為信陵君。", literal: "3 King Anxi of Wei enfeoffed his younger brother Wuji as Lord Xinling.", idiomatic: "3 King Anxi of Wei enfeoffed his younger brother Wuji as Lord Xinling." },
  { zh: "秦相國穰侯伐魏。", literal: "Qin's chancellor, the Marquis of Rang, attacked Wei.", idiomatic: "Qin's chancellor, the Marquis of Rang, attacked Wei." },
  { zh: "韓暴鳶救魏，穰侯大破之，斬首四萬。", literal: "Han sent Bao Yuan to rescue Wei; the Marquis of Rang routed him and beheaded forty thousand.", idiomatic: "Han sent Bao Yuan to rescue Wei. The Marquis of Rang routed him and beheaded forty thousand." },
  { zh: "暴鳶走啟封。", literal: "Bao Yuan fled to Qifeng.", idiomatic: "Bao Yuan fled to Qifeng." },
  { zh: "魏納八城以和。", literal: "Wei yielded eight cities to make peace.", idiomatic: "Wei yielded eight cities to make peace." },
  { zh: "穰侯復伐魏，走芒卯，入北宅。", literal: "The Marquis of Rang again attacked Wei, routed Mang Mao, and entered Beizhai.", idiomatic: "The Marquis of Rang again attacked Wei, routed Mang Mao, and entered Beizhai." },
  { zh: "〔遂圍大梁〕<ref>〔遂圍大梁〕章校「十二行本『魏』上有『遂圍大梁』四字；", literal: "〔then besieged Daliang〕<ref>〔then besieged Daliang〕Zhang's collation: “In the twelve-line edition, above ‘Wei’ are the four characters ‘then besieged Daliang’;", idiomatic: "〔then besieged Daliang〕<ref>〔then besieged Daliang〕Zhang's collation: “In the twelve-line edition, above ‘Wei’ are the four characters ‘then besieged Daliang’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai's collation agrees.", idiomatic: "Tui Zhai's collation agrees." },
  { zh: "」據補。", literal: "” supplemented accordingly.", idiomatic: "” supplemented accordingly." },
  { zh: "</ref>，魏人割溫以和。", literal: "</ref> the men of Wei ceded Wen to make peace.", idiomatic: "</ref> the men of Wei ceded Wen to make peace." },
  { zh: "1魏復與齊合從。", literal: "1 Wei again joined Qi in a horizontal alliance.", idiomatic: "1 Wei again joined Qi in a horizontal alliance." },
  { zh: "秦穰侯伐魏，拔四城，斬首四萬。", literal: "Qin's Marquis of Rang attacked Wei, took four cities, and beheaded forty thousand.", idiomatic: "Qin's Marquis of Rang attacked Wei, took four cities, and beheaded forty thousand." },
  { zh: "1趙人、魏人伐韓華陽。", literal: "1 The men of Zhao and Wei attacked Hua-yang in Han.", idiomatic: "1 Zhao and Wei attacked Hua-yang in Han." },
  { zh: "韓人告急於秦，秦王弗救。", literal: "The men of Han reported urgency to Qin; the king of Qin did not rescue them.", idiomatic: "Han appealed to Qin for aid; the king of Qin did not send help." },
  { zh: "韓相國謂陳筮曰：「事急矣！", literal: "Han's chancellor said to Chen She, “The matter is urgent!", idiomatic: "Han's chancellor said to Chen She, “This is urgent!" },
  { zh: "願公雖病，為一宿之行。", literal: "Though you are ill, I beg you to make a one-night journey.", idiomatic: "Though you are ill, I beg you to make an overnight journey." },
  { zh: "」陳筮如秦，見穰侯。", literal: "” Chen She went to Qin and saw the Marquis of Rang.", idiomatic: "” Chen She went to Qin and saw the Marquis of Rang." },
  { zh: "穰侯曰：「事急乎？", literal: "The Marquis of Rang said, “Is the matter urgent?", idiomatic: "The Marquis of Rang said, “Is it urgent?" },
  { zh: "故使公來。", literal: "That is why you were sent.", idiomatic: "That is why you were sent." },
  { zh: "」陳筮曰：「未急也。", literal: "” Chen She said, “Not yet urgent.", idiomatic: "” Chen She said, “Not yet." },
  { zh: "」穰侯怒曰：「何也？", literal: "” The Marquis of Rang said angrily, “How so?", idiomatic: "” The Marquis of Rang said angrily, “How so?" },
  { zh: "」陳筮曰：「彼韓急則將變而他從；", literal: "” Chen She said, “If Han were urgent they would change and follow another;", idiomatic: "” Chen She said, “If Han were desperate they would turn elsewhere;" },
  { zh: "以未急，故復來耳。", literal: "because they are not yet urgent, they have come again—that is all.", idiomatic: "because they are not desperate yet, they have come again—that is all." },
  { zh: "」穰侯曰：「請發兵矣。", literal: "” The Marquis of Rang said, “I beg leave to send troops.", idiomatic: "” The Marquis of Rang said, “I will send troops." },
  { zh: "」乃與武安君及客卿胡陽救韓，八日而至，敗魏軍於華陽之下，走芒卯，虜三將，斬首十三萬。", literal: "” He then with Lord Wu'an and the guest-minister Hu Yang rescued Han; in eight days they arrived, defeated Wei's army below Hua-yang, routed Mang Mao, captured three generals, and beheaded a hundred thirty thousand.", idiomatic: "” He then marched with Lord Wu'an and the guest-minister Hu Yang to rescue Han, arrived in eight days, defeated Wei's army below Hua-yang, routed Mang Mao, captured three generals, and beheaded a hundred thirty thousand." },
  { zh: "武安君又與趙將賈偃戰，沈其卒二萬人於河。", literal: "Lord Wu'an again fought Zhao's general Jia Yan and sank twenty thousand of his soldiers in the river.", idiomatic: "Lord Wu'an again fought Zhao's general Jia Yan and drowned twenty thousand of his men in the river." },
  { zh: "魏段干子請割南陽予秦以和。", literal: "Wei sent Duan Ganzi to ask to cede Nanyang to Qin for peace.", idiomatic: "Wei sent Duan Ganzi to offer Nanyang to Qin for peace." },
  { zh: "蘇代謂魏王曰：「欲璽者，段干子也；", literal: "Su Dai said to the king of Wei, “The one who wants the seal is Duan Ganzi;", idiomatic: "Su Dai said to the king of Wei, “The one who wants the seal is Duan Ganzi;" },
  { zh: "欲地者，秦也。", literal: "the one who wants the land is Qin.", idiomatic: "the one who wants the land is Qin." },
  { zh: "今王使欲地者制璽，欲璽者制地，魏地盡矣！", literal: "Now if Your Majesty lets the one who wants land control the seal and the one who wants the seal control the land, Wei's territory will be exhausted!", idiomatic: "Now you let the one who wants land control the seal and the one who wants the seal control the land—Wei will lose everything!" },
  { zh: "夫以地事秦，猶抱薪救火，薪不盡，火不滅。", literal: "Serving Qin with land is like carrying firewood to put out a fire—as long as the firewood is not exhausted, the fire is not extinguished.", idiomatic: "Feeding Qin with land is like carrying firewood to a fire—as long as the wood lasts, the fire will not die." },
  { zh: "」王曰：「是則然也。", literal: "” The king said, “That is so.", idiomatic: "” The king said, “That is true." },
  { zh: "雖然，事始已行，不可更矣！", literal: "Even so, the matter has already begun and cannot be changed!", idiomatic: "Still, the matter has already begun and cannot be changed!" },
  { zh: "」對曰：「夫博之所以貴梟者，便則食，不便則止。", literal: "” He replied, “The reason gaming values the owl token is that when convenient one eats, when inconvenient one stops.", idiomatic: "” He replied, “In gaming the owl token is prized because you play when it helps and stop when it does not." },
  { zh: "今何王之用智不如用梟也？", literal: "Why does Your Majesty use wisdom less well than using the owl?", idiomatic: "Why does Your Majesty use less sense than an owl token?" },
  { zh: "」魏王不聽，卒以南陽為和，實修武。", literal: "” The king of Wei did not listen; in the end he made peace with Nanyang—in fact Xiuwu.", idiomatic: "” The king of Wei would not listen. In the end he ceded Nanyang for peace—in fact Xiuwu." },
  { zh: "2韓釐王薨，子桓惠王立。", literal: "2 King Xi of Han died; his son King Huanhui succeeded.", idiomatic: "2 King Xi of Han died; his son King Huanhui succeeded." },
  { zh: "3韓、魏既服於秦，秦王將使武安君與韓、魏伐楚，未行，而楚使者黃歇至，聞之，畏秦乘勝一舉而滅楚也，乃上書曰：「臣聞物至則反，冬、夏是也；", literal: "3 Han and Wei having submitted to Qin, the king of Qin was about to send Lord Wu'an with Han and Wei to attack Chu. Before they marched, Chu's envoy Huang Xie arrived; hearing this, he feared Qin would ride victory in one stroke and destroy Chu, and submitted a memorial, saying, “Your servant has heard that when things reach their limit they reverse—winter and summer are so;", idiomatic: "3 After Han and Wei had submitted to Qin, the king of Qin was about to send Lord Wu'an with Han and Wei against Chu. Before they marched, Chu's envoy Huang Xie arrived. Fearing Qin would ride victory and destroy Chu in one blow, he submitted a memorial: “I have heard that when things reach their limit they reverse—winter and summer are so;" },
  { zh: "致至則危，累棋是也。", literal: "when piled to the limit they become perilous—stacked chess pieces are so.", idiomatic: "when piled to the limit they topple—stacked chess pieces are so." },
  { zh: "今大國之地，遍天下有其二垂，此從生民已來，萬乘之地未嘗有也。", literal: "Now the great state's territory spans the world and holds two of its quarters; since the birth of the people, a realm of ten thousand chariots has never had the like.", idiomatic: "Your great state's lands now span the world and hold two of its quarters—since mankind began, no realm of ten thousand chariots has ever held so much." },
  { zh: "先王三世不忘接地於齊，以絕從親之要。", literal: "For three generations the former kings never forgot to join territory with Qi, to cut off the vital point of horizontal alliances.", idiomatic: "For three generations your forebears never ceased pressing against Qi, to sever the throat of horizontal alliances." },
  { zh: "今王使盛橋守事於韓，盛橋以其地入秦，是王不用甲，不信威，而得百里之地，王可謂能矣！", literal: "Now Your Majesty sent Sheng Qiao to hold affairs in Han, and Sheng Qiao brought his territory into Qin—Your Majesty used no armor, relied on no mere show of force, and gained a hundred li of land; Your Majesty may be called capable!", idiomatic: "You sent Sheng Qiao to hold affairs in Han, and he brought his territory into Qin—you used no armor, no empty threat, and gained a hundred li of land. You may be called capable!" },
  { zh: "王又舉甲而攻魏，杜大樑之門，舉河內，拔燕、酸棗、虛、桃，入邢，魏之兵雲翔而不敢救，王之功亦多矣！", literal: "Your Majesty again raised armor and attacked Wei, shut the gates of Daliang, took Henei, seized Yan, Suanzao, Xu, and Tao, entered Xing—Wei's troops clouded the sky yet dared not rescue; Your Majesty's achievements are many!", idiomatic: "You again raised armies against Wei, shut Daliang's gates, took Henei, seized Yan, Suanzao, Xu, and Tao, entered Xing—Wei's troops swarmed like clouds yet dared not rescue. Your achievements are many!" },
  { zh: "王休甲息眾，二年而後復之，又並蒲、衍、首、垣以臨仁、平丘，黃、濟陽嬰城而魏氏服。", literal: "Your Majesty rested armor and eased the masses; after two years you resumed, again united Pu, Yan, Shou, and Yuan to overlook Ren and Pingqiu—Huang and Jiyang held their walls tight and Wei submitted.", idiomatic: "You rested your armies and eased your people; two years later you resumed, united Pu, Yan, Shou, and Yuan to overlook Ren and Pingqiu, and with Huang and Jiyang walled tight Wei submitted." },
  { zh: "王又割濮磨之北，注齊、秦之要，絕楚、趙之脊，天下五合六聚而不敢救，王之威亦單矣！", literal: "Your Majesty again cut north of Pu and Mo, poured into the vital points of Qi and Qin, severed the spine of Chu and Zhao—the world five times united and six times gathered yet dared not rescue; Your Majesty's majesty stands alone!", idiomatic: "You again cut north of Pu and Mo, struck at Qi and Qin's vital points, severed Chu and Zhao's spine—the world united again and again yet dared not rescue. Your majesty stands alone!" },
  { zh: "王若能保功守威，絀攻取之心，而肥仁義之地，使無後患，三王不足四，五伯不足六也！", literal: "If Your Majesty can preserve achievement and guard majesty, restrain the heart of attack and seizure, and enrich the ground of benevolence and righteousness so there are no later troubles, the Three Kings are not enough for a fourth, the Five Hegemons not enough for a sixth!", idiomatic: "If you can preserve your gains and guard your prestige, curb the urge to seize, and enrich the ground of benevolence and righteousness so there are no later troubles, you will outdo the Three Kings and surpass the Five Hegemons!" },
  { zh: "王若負人徒之眾，仗兵革之強，乘毀魏之威，而欲以力臣天下之主，臣恐其有後患也。", literal: "If Your Majesty relies on the multitude of men and followers, trusts in the strength of arms, rides the prestige of destroying Wei, and wishes by force to make the world's lords your subjects, your servant fears there will be later troubles.", idiomatic: "If you rely on your masses, trust in arms, ride the prestige of crushing Wei, and mean to force the world's lords into subjection, I fear later troubles." },
  { zh: "《詩》曰：『靡不有初，鮮克有終。", literal: "The Odes say: ‘There is nothing without a beginning; few reach the end.", idiomatic: "The Odes say: ‘Nothing lacks a beginning; few reach the end." },
  { zh: "』《易》曰：『狐涉水，濡其尾。", literal: "’ The Changes say: ‘The fox crosses the water and wets its tail.", idiomatic: "’ The Changes say: ‘The fox crosses the water and wets its tail." },
  { zh: "』此言始之易，終之難也。", literal: "’ This speaks of how beginnings are easy and endings hard.", idiomatic: "’ This means beginnings are easy and endings hard." },
  { zh: "昔吳之信越也，從而伐齊，既勝齊人於艾陵，還為越禽於三江之浦。", literal: "Formerly Wu trusted Yue and followed them to attack Qi; having defeated the men of Qi at Ailing, on return Wu was taken by Yue at the mouth of the Three Rivers.", idiomatic: "Once Wu trusted Yue, followed them against Qi, defeated Qi at Ailing, and on the way home was captured by Yue at the mouth of the Three Rivers." },
  { zh: "智氏之信韓、魏也，從而伐趙，攻晉陽城，勝有日矣，韓、魏叛之，殺智伯瑤於鑿台之下。", literal: "The house of Zhi trusted Han and Wei and followed them to attack Zhao; they besieged Jinyang, victory was near, Han and Wei rebelled, and killed Zhi Bo Yao below the Zao Terrace.", idiomatic: "The house of Zhi trusted Han and Wei, followed them against Zhao, besieged Jinyang with victory near, then Han and Wei rebelled and killed Zhi Bo Yao below the Zao Terrace." },
  { zh: "今王妒楚之不毀，而忘毀楚之強韓、魏也，臣為王慮而不取也。", literal: "Now Your Majesty resents that Chu is not destroyed, yet forgets that destroying Chu strengthens Han and Wei—your servant counsels Your Majesty not to take this course.", idiomatic: "You resent that Chu is not destroyed, yet forget that destroying Chu strengthens Han and Wei. I urge you not to take this course." },
  { zh: "夫楚國，援也；", literal: "Chu is a support;", idiomatic: "Chu is a support;" },
  { zh: "鄰國，敵也。", literal: "neighboring states are enemies.", idiomatic: "neighboring states are enemies." },
  { zh: "今王信韓、魏之善王，此正吳之信越也，臣恐韓、魏卑辭除患而實欲欺大國也。", literal: "Now Your Majesty trusts Han and Wei's goodwill toward you—this is exactly Wu trusting Yue; your servant fears Han and Wei with humble words remove trouble but in truth wish to deceive the great state.", idiomatic: "You trust Han and Wei's goodwill—this is Wu trusting Yue again. I fear they speak humbly to remove danger but in truth mean to deceive your great state." },
  { zh: "何則？", literal: "Why?", idiomatic: "Why?" },
  { zh: "王無重世之德於韓、魏而有累世之怨焉。", literal: "Your Majesty has no virtue piled over generations toward Han and Wei, but grudges piled over generations.", idiomatic: "You have heaped no kindness on Han and Wei over generations, but heaped grudges over generations." },
  { zh: "夫韓、魏父子兄弟接踵而死於秦〔者〕將十世矣<ref>夫韓魏父子兄弟接踵而死於秦〔者〕將十世矣章校「十二行本『秦』下有『者』字；", literal: "The fathers, sons, and brothers of Han and Wei who died in succession at Qin's hands 〔者〕 approach ten generations<ref>Fathers, sons, and brothers of Han and Wei who died in succession at Qin's hands 〔者〕 approach ten generations—Zhang's collation: “In the twelve-line edition, below ‘Qin’ is the character ‘者’;", idiomatic: "Fathers, sons, and brothers of Han and Wei who died in succession at Qin's hands 〔者〕 approach ten generations<ref>Fathers, sons, and brothers of Han and Wei who died in succession at Qin's hands 〔者〕 approach ten generations—Zhang's collation: “In the twelve-line edition, below ‘Qin’ is the character ‘者’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong's edition agrees.", idiomatic: "Kong's edition agrees." },
  { zh: "」據補。", literal: "” supplemented accordingly.", idiomatic: "” supplemented accordingly." },
  { zh: "</ref>，故韓、魏之不亡，秦社稷之憂也。", literal: "</ref> therefore Han and Wei's not perishing is the worry of Qin's altars of soil and grain.", idiomatic: "</ref> therefore as long as Han and Wei do not perish, they are the worry of Qin's altars." },
  { zh: "今王資之與攻楚，不亦過乎！", literal: "Now if Your Majesty supplies them to attack Chu, is that not excessive!", idiomatic: "Now to arm them to attack Chu—is that not going too far!" },
  { zh: "且攻楚將惡出兵？", literal: "Moreover, attacking Chu—how will you send troops?", idiomatic: "Moreover, attacking Chu—how will you march?" },
  { zh: "王將借路於仇讎之韓、魏乎？", literal: "Will Your Majesty borrow a route through Han and Wei, your mortal foes?", idiomatic: "Will you borrow a route through Han and Wei, your mortal foes?" },
  { zh: "兵出之日而王憂其不反也。", literal: "The day the army marches forth Your Majesty will worry that it does not return.", idiomatic: "The day your army marches out you will fear it will not return." },
  { zh: "王若不借路於仇讎之韓、魏，必攻隨水右壤，此皆廣川、大水、山林、溪谷，不食之地。", literal: "If Your Majesty does not borrow a route through Han and Wei, your foes, you must attack the right bank of the Sui—all broad rivers, great waters, mountains, forests, ravines, and gorges, lands that yield no food.", idiomatic: "If you do not borrow a route through Han and Wei, your foes, you must attack the right bank of the Sui—all broad rivers, great floods, mountains, forests, and ravines, lands that yield no food." },
  { zh: "是王有毀楚之名而無得地之實也。", literal: "Then Your Majesty will have the name of destroying Chu but not the reality of gaining land.", idiomatic: "Then you will earn the name of destroying Chu but gain no land." },
  { zh: "且王攻楚之日，四國必悉起兵以應王。", literal: "Moreover, on the day Your Majesty attacks Chu, the four states will surely all raise troops to respond to Your Majesty.", idiomatic: "Moreover, the day you attack Chu, the four states will surely all raise troops against you." },
  { zh: "秦、楚之兵構而不離；", literal: "Qin and Chu's armies will be locked and not part;", idiomatic: "Qin and Chu will be locked in battle and unable to break off;" },
  { zh: "魏氏將出而攻留、方輿、銍、湖陵、碭、蕭、相，故宋必盡；", literal: "Wei will march out and attack Liu, Fangyu, Zhi, Huling, Dang, Xiao, and Xiang—the old lands of Song will all be gone;", idiomatic: "Wei will march out against Liu, Fangyu, Zhi, Huling, Dang, Xiao, and Xiang—the old lands of Song will all be lost;" },
  { zh: "齊人南面攻楚，泗上必舉。", literal: "the men of Qi will attack Chu from the south; the lands above the Si will surely fall.", idiomatic: "Qi will attack Chu from the north; the lands above the Si will surely fall." },
  { zh: "此皆平原四達膏腴之地。", literal: "These are all level plains open on four sides, rich and fertile lands.", idiomatic: "These are all level plains with roads in every direction, rich and fertile country." },
  { zh: "如此，則天下之國莫強於齊、魏矣。", literal: "If so, then among states under Heaven none will be stronger than Qi and Wei.", idiomatic: "If things go thus, then among the states of the world none will be stronger than Qi and Wei." },
  { zh: "臣為王慮，莫若善楚。", literal: "Your servant has considered for Your Majesty: nothing is better than treating Chu well.", idiomatic: "I have weighed matters for Your Majesty: you had best befriend Chu." },
  { zh: "秦、楚合而為一以臨韓，韓必斂手而朝；", literal: "If Qin and Chu unite as one to face Han, Han will surely fold its hands and pay court;", idiomatic: "If Qin and Chu unite and press Han, Han will surely fold its hands and submit;" },
  { zh: "王施以東山之險，帶以曲河之利，韓必為關內之侯。", literal: "Your Majesty deploying the danger of the eastern hills, girding with the advantage of the winding rivers, Han will surely become a marquis within the pass.", idiomatic: "Deploy the heights of the eastern hills and bind them with the advantage of the winding rivers, and Han will surely become a marquis of the inner domain." },
  { zh: "若是而王以十萬戍鄭，梁氏寒心，許、鄢陵嬰城而上蔡、召陵不往來也。", literal: "If so, and Your Majesty garrisons Zheng with a hundred thousand, the house of Liang will lose heart; Xu and Yanling will wall their cities; and Shangcai and Shaoling will have no coming and going.", idiomatic: "Then, if Your Majesty stations a hundred thousand at Zheng, Wei will lose heart; Xu and Yanling will shut their walls; Shangcai and Shaoling will cease their traffic." },
  { zh: "如此，魏亦關內侯矣。", literal: "If so, Wei too will be a marquis within the pass.", idiomatic: "If so, Wei too will be a marquis of the inner domain." },
  { zh: "王壹善楚而關內兩萬乘之主注地於齊，齊右壤可拱手而取也。", literal: "If Your Majesty befriends Chu in one stroke and the two lords of ten thousand chariots within the pass pour territory toward Qi, Qi's right lands can be taken with folded hands.", idiomatic: "Befriend Chu outright, and when the two ten-thousand-chariot lords within the pass turn their lands toward Qi, you can take Qi's right flank with folded hands." },
  { zh: "王之地一經兩海，要約天下，是燕、趙無齊、楚，齊、楚無燕、趙也。", literal: "Your Majesty's lands running through both seas, binding the world under key terms—Yan and Zhao will lack Qi and Chu, Qi and Chu will lack Yan and Zhao.", idiomatic: "Your lands will span both seas and bind the world by strategic holds; Yan and Zhao will lack Qi and Chu, and Qi and Chu will lack Yan and Zhao." },
  { zh: "然後危動燕、趙，直搖齊、楚，此四國者不待痛而服矣。", literal: "Then threaten and stir Yan and Zhao, shake Qi and Chu directly—these four states will submit without being wounded.", idiomatic: "Then alarm Yan and Zhao and shake Qi and Chu directly—these four states will yield without your needing to wound them." },
  { zh: "」王從之，止武安君而謝韓、魏，使黃歇歸，約親於楚。", literal: "” The king followed this, stopped the Lord of Wu'an and apologized to Han and Wei, sent Huang Xie home, and pledged kinship with Chu.", idiomatic: "” The king accepted this, held back the Lord of Wu'an and made apology to Han and Wei, sent Huang Xie home, and pledged alliance with Chu." },
  { zh: "<divclass=\"references-small\"><references/></div>", literal: "<divclass=\"references-small\"><references/></div>", idiomatic: "<divclass=\"references-small\"><references/></div>" },
  { zh: "周", literal: "Zhou", idiomatic: "Zhou" }
];
